import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { SidebarComponent } from './components/sidebar/sidebar.component';
import { LayoutComponent } from './containers/layout/layout.component';
import { HomeComponent } from './containers/home/home.component';
import { MatchWithEventBetTypesComponent } from './containers/match-with-event-bet-types/match-with-event-bet-types.component';
import { VirtualRunnersComponent } from './containers/virtual-runners-component/virtual-runners.component';
import { RaceLayoutComponent } from './containers/race-layout/race-layout.component';
import { VirtualEventBetTypeItemsComponent } from './containers/virtual-event-bet-type-items/virtual-event-bet-type-items.component';
import { VirtualEventBetTypesComponent } from './containers/virtual-event-bet-types/virtual-event-bet-types.component';
import { EventCategoryWithEventsComponent } from './containers/eventcategory-with-events/eventcategory-with-events.component';
import { EventCategoryLayoutComponent } from './containers/eventcategory-layout/eventcategory-layout.component';
import { NumbersGameComponent } from './containers/numbers-game/numbers-game.component';
import { InstantLeagueLayoutComponent } from './containers/instant-league-layout/instant-league-layout.component';
import { InstantLeagueMatchesComponent } from './components/instant-league-matches/instant-league-matches.component';
import { InstantLeagueRankingComponent } from './components/instant-league-ranking/instant-league-ranking.component';
import { InstantLeagueResultsComponent } from './components/instant-league-results/instant-league-results.component';
const routes: Routes = [
  {
    path: '',
    component: LayoutComponent,
    children: [
      { path: '', component: HomeComponent },
      {
        path: 'category/:eventCategoryId',
        component: EventCategoryLayoutComponent,
        children: [
          {
            path: '',
            component: EventCategoryWithEventsComponent
          },
          {
            path: 'race/:eventId',
            component: RaceLayoutComponent,
            children: [
              {
                path: '',
                component: VirtualEventBetTypesComponent
              },
              {
                path: ':eventBetTypeId/items',
                component: VirtualEventBetTypeItemsComponent
              },
              {
                path: ':eventBetTypeId/runners',
                component: VirtualRunnersComponent
              }
            ]
          },
          {
            path: 'numbers-game/:eventId',
            component: NumbersGameComponent,
            children: [
              {
                path: '',
                component: VirtualEventBetTypesComponent
              },
              {
                path: ':eventBetTypeId/items',
                component: VirtualEventBetTypeItemsComponent
              }
            ]
          },
          { path: 'match/:match', component: MatchWithEventBetTypesComponent }
        ]
      },
      {
        path: 'category/instant-league/:eventCategoryId',
        component: InstantLeagueLayoutComponent,
        children: [
          {
            path: '',
            redirectTo: 'matches',
            pathMatch: 'full'
          },
          {
            path: 'matches',
            component: InstantLeagueMatchesComponent
          },
          {
            path: 'results',
            component: InstantLeagueResultsComponent
          },
          {
            path: 'ranking',
            component: InstantLeagueRankingComponent
          }
        ]
      }
    ]
  },
  { path: '', outlet: 'sidebar', component: SidebarComponent }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgVirtualRoutingModule {}
