import {
  Component,
  ChangeDetectionStrategy,
  Inject,
  PLATFORM_ID,
  Input,
  ChangeDetectorRef,
  OnInit,
  Output,
  EventEmitter
} from '@angular/core';

import { ApplicationStateService, DestroySubject } from '@honoregaming/core';
import { interval } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import {
  MATCH_DURATION,
  RESULTS_DURATION,
  THRESHOLD_BEFORE_FETCH_RESULT
} from '../../constants/intant-league-round.consts';
import { isPlatformBrowser } from '@angular/common';
@Component({
  selector: 'hg-instant-league-round-picker',
  templateUrl: './instant-league-round-picker.component.html',
  styleUrls: ['./instant-league-round-picker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantLeagueRoundPickerComponent extends DestroySubject implements OnInit {
  loading = false;
  goalsFetched = false;

  @Input() rounds: { id: number; roundNumber: number; time: Date }[];
  @Input() roundDuration: number;

  @Output() activeRoundUpdate: EventEmitter<number> = new EventEmitter();
  @Output() liveTimerUpdate: EventEmitter<{ minute: number; id: number }> = new EventEmitter();
  @Output() fetchRoundPlayout: EventEmitter<number> = new EventEmitter();
  @Output() loadNextRound: EventEmitter<{ time: Date; id: number }> = new EventEmitter();

  liveInterval: NodeJS.Timeout;
  liveTimeLeft: number;
  livePercentageProgress: number;
  liveMinuteDisplayed: number;
  resultsTimeLeft: number;
  resultsPercentageProgress: number;

  minutesBeforeStart: number;
  secondsBeforeStart: number;

  selectedRoundId: number;
  now: Date;

  roundIds: number[];

  constructor(
    @Inject(PLATFORM_ID) private platformId,
    private cdr: ChangeDetectorRef,
    private applicationStateService: ApplicationStateService
  ) {
    super();
  }

  ngOnInit() {
    this.roundIds = this.rounds.map(x => x.id);
    this.selectedRoundId = this.roundIds[0];
    this.updateCountDownUntilLive();
    if (isPlatformBrowser(this.platformId)) {
      this.applicationStateService.isReady$.subscribe(() => {
        this.setClock();
      });
    }
  }

  setClock() {
    interval(1000)
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        if (this.rounds.length) {
          this.updateCountDownUntilLive();
        }
      });
  }

  updateCountDownUntilLive() {
    const nextRound = this.rounds.filter(x => x.time > new Date())[0];
    const timeBeforeStart = (nextRound.time.getTime() - new Date().getTime()) / 1000;
    this.minutesBeforeStart = Math.trunc(timeBeforeStart / 60);
    this.secondsBeforeStart =
      Math.round(timeBeforeStart % 60) === 0 ? Math.round(timeBeforeStart % 60) : Math.round(timeBeforeStart % 60) - 1;
    this.now = new Date();

    // Check if it is time to fetch event playouts
    if (
      this.rounds[0].time < new Date(new Date().getTime() + THRESHOLD_BEFORE_FETCH_RESULT * 1000) &&
      !this.goalsFetched
    ) {
      this.fetchRoundPlayout.emit(this.rounds[0].id);
      this.goalsFetched = true;
    }

    // Check if it is time to start the round
    if (this.rounds[0].time < this.now && !this.liveInterval) {
      this.startLiveTimer();
    }

    this.cdr.detectChanges();
  }

  startLiveTimer() {
    const alreadySpentTimeInMatch = Math.trunc(
      ((new Date().getTime() / 1000 - this.rounds[0].time.getTime() / 1000) * MATCH_DURATION) / this.roundDuration
    );
    this.liveTimeLeft = MATCH_DURATION - alreadySpentTimeInMatch;
    this.livePercentageProgress = (100 * (MATCH_DURATION - this.liveTimeLeft)) / MATCH_DURATION;
    this.liveMinuteDisplayed = Math.round((this.livePercentageProgress / 100) * MATCH_DURATION);

    this.liveInterval = setInterval(() => {
      if (this.liveTimeLeft > 0) {
        this.liveTimeLeft--;
        this.livePercentageProgress = (100 * (MATCH_DURATION - this.liveTimeLeft)) / MATCH_DURATION;
        this.liveMinuteDisplayed = Math.round((this.livePercentageProgress / 100) * MATCH_DURATION);
        this.liveTimerUpdate.emit({ minute: MATCH_DURATION - this.liveTimeLeft, id: this.rounds[0].id });
      } else {
        this.resultsTimeLeft = RESULTS_DURATION;
        this.liveTimeLeft = 0;
        this.cdr.markForCheck();
        clearInterval(this.liveInterval);
        this.liveInterval = undefined;
        this.liveInterval = setInterval(() => {
          if (this.resultsTimeLeft > 0) {
            this.resultsTimeLeft--;
            this.resultsPercentageProgress = (100 * (RESULTS_DURATION - this.resultsTimeLeft)) / RESULTS_DURATION;
          } else {
            this.pauseTimer();
            this.goalsFetched = false;
          }
          this.cdr.markForCheck();
        }, 50);
      }
      this.cdr.detectChanges();
    }, (1000 * this.roundDuration) / MATCH_DURATION);
  }

  pauseTimer() {
    clearInterval(this.liveInterval);
    this.liveInterval = undefined;
    this.liveTimerUpdate.emit({ minute: -1, id: this.rounds[0].id });
    if (this.rounds[0].id === this.selectedRoundId) {
      this.changeRound(this.rounds[1].id);
    }
    this.loadNextRound.emit(this.rounds[this.rounds.length - 1]);
  }

  changeRound(id: number) {
    this.selectedRoundId = id;
    this.activeRoundUpdate.emit(id);
  }

  trackRound(_index: number, round: { id: number; time: Date }) {
    return round.id;
  }
}
