import { Component, ChangeDetectionStrategy, OnInit, Input, ChangeDetectorRef, Inject } from '@angular/core';
import { DestroySubject, navigationServiceToken, INavigationService } from '@honoregaming/core';
import { Event, EventCategory } from '@honoregaming/types';
import { EventsService, EventCategoriesService } from '@honoregaming/events';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-customer-spin-and-win-details',
  templateUrl: './spin-and-win-details.component.html',
  styleUrls: ['./spin-and-win-details.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinDetailsComponent extends DestroySubject implements OnInit {
  @Input()
  public eventId: number;

  public event: Event;
  public eventCategory: EventCategory;

  constructor(
    private eventsService: EventsService,
    private eventCategoryService: EventCategoriesService,
    private cdRef: ChangeDetectorRef,
    @Inject(navigationServiceToken) private navigationService: INavigationService
  ) {
    super();
  }

  ngOnInit() {
    const event = this.eventsService.getEventFromCache(this.eventId);
    if (!event) {
      this.eventsService
        .getEventDetails(this.eventId)
        .pipe(takeUntil(this.destroy$))
        .subscribe(e => {
          if (e) {
            this.event = e;
            this.getEventCategoryForEventEntryPoint(this.event.entryPointId);
          }
        });
    } else {
      this.event = event;
      this.getEventCategoryForEventEntryPoint(this.event.entryPointId);
    }
  }

  private getEventCategoryForEventEntryPoint(entryPointId: number): void {
    this.eventCategoryService
      .getEntryPoints()
      .pipe(takeUntil(this.destroy$))
      .subscribe(eventCategories => {
        this.eventCategory = eventCategories.find(ec => ec.id === entryPointId);
        this.cdRef.markForCheck();
      });
  }

  public goBack(): void {
    this.navigationService.goBack();
  }
}
