import {
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Component,
  OnChanges,
  ChangeDetectorRef,
  Inject,
  PLATFORM_ID,
  NgZone,
  EventEmitter,
  Output
} from '@angular/core';
import {
  Race,
  EventWithEventBetTypes,
  SelectableEventBetTypeItem,
  EventBetType,
  EventBetTypeItem
} from '@honoregaming/types';
import { EventCategoriesService } from '@honoregaming/events';
import { DestroySubject, delayBetween, getUtcNow, ApplicationStateService } from '@honoregaming/core';
import { Subscription, timer } from 'rxjs';
import { takeUntil } from 'rxjs/operators';
import { isPlatformBrowser } from '@angular/common';
@Component({
  selector: 'hg-virtual-race',
  templateUrl: './virtual-race.component.html',
  styleUrls: ['./virtual-race.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class VirtualRaceComponent extends DestroySubject implements OnInit, OnChanges {
  @Input()
  race: EventWithEventBetTypes<Race>;
  @Input()
  showEntrypoint: boolean;
  @Input()
  showEntryPointName: boolean;
  @Input()
  flatMode: boolean;
  @Input()
  isAboutToStart: boolean;
  @Input()
  showTimer: boolean;
  @Output()
  betSelectionChanged = new EventEmitter<{
    item: EventBetTypeItem;
    selected: boolean;
  }>();

  entryPointName: string;
  countDown: number;

  timerCountDown: Subscription;

  winnerEventBetType: EventBetType;
  favoritesEventBetTypeItems: SelectableEventBetTypeItem[];

  constructor(
    private eventCategoryService: EventCategoriesService,
    private cdRef: ChangeDetectorRef,
    @Inject(PLATFORM_ID) private platformId,
    private zone: NgZone,
    private applicationStateService: ApplicationStateService
  ) {
    super();
  }

  ngOnInit() {
    this.winnerEventBetType = this.race.eventBetTypes?.find(ebt => ebt.betTypeId === 30001);
    const winnerEventBetTypeItems = this.winnerEventBetType?.eventBetTypeItems;

    if (winnerEventBetTypeItems?.length) {
      this.favoritesEventBetTypeItems = winnerEventBetTypeItems.sort((a, b) => (a.odds > b.odds ? 1 : -1)).slice(0, 3);
    }

    if (this.showEntryPointName) {
      this.eventCategoryService
        .getEntryPoints()
        .pipe(takeUntil(this.destroy$))
        .subscribe(ep => {
          const eventCategory = ep.find(e => e.id === this.race.entryPointId);
          if (eventCategory) {
            this.entryPointName = eventCategory.name;
          }
        });
    }
  }

  ngOnChanges(): void {
    if (this.showTimer && isPlatformBrowser(this.platformId)) {
      this.applicationStateService.isReady$.subscribe(() => {
        if (this.timerCountDown) {
          this.timerCountDown.unsubscribe();
        }

        this.timerCountDown = timer(0, 1000)
          .pipe(takeUntil(this.destroy$))
          .subscribe(_ => {
            this.countDown = delayBetween(getUtcNow(), this.race.expectedStart);
            this.zone.run(() => this.cdRef.markForCheck());
          });
      });
    }

    if (this.showEntryPointName) {
      this.eventCategoryService
        .getEntryPoints()
        .pipe(takeUntil(this.destroy$))
        .subscribe(ep => {
          const eventCategory = ep.find(e => e.id === this.race.entryPointId);
          if (eventCategory) {
            this.entryPointName = eventCategory.name;
            this.cdRef.markForCheck();
          }
        });
    }
  }

  toggleBet(item: SelectableEventBetTypeItem) {
    this.betSelectionChanged.emit({
      item: item,
      selected: !item.selected
    });
  }

  trackEventBetTypeItem(_index, eventBetTypeItem: SelectableEventBetTypeItem) {
    return eventBetTypeItem.id;
  }
}
