import { Component, ChangeDetectionStrategy, OnInit, Input, Output, EventEmitter, OnChanges } from '@angular/core';
import { SelectableEventBetTypeItem } from '@honoregaming/types';
import { RouletteItemSize } from '@honoregaming/ui';

@Component({
  selector: 'hg-spin-and-win-six',
  templateUrl: './spin-and-win-six.component.html',
  styleUrls: ['./spin-and-win-six.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinSixComponent implements OnInit, OnChanges {
  @Input()
  eventBetTypeItems: SelectableEventBetTypeItem[];
  orderedEventBetTypeItems: SelectableEventBetTypeItem[] = [];

  @Output()
  selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  RouletteItemSize = RouletteItemSize;
  items: number[][] = [[], [], [], [], [], [], [], [], [], [], [], []];

  constructor() {}

  ngOnInit() {
    // Creates the 12 sets of 6 roulette items to display
    let line = 0;
    let rewind = true;
    for (let i = 1; i < 37; i++) {
      this.items[line].push(i);
      if (i % 3 === 0) {
        if (!rewind) {
          i = i - 3;
          line++;
        }
        rewind = !rewind;
      }
    }
    this.items.pop();
  }

  ngOnChanges() {
    this.orderedEventBetTypeItems = [];
    for (let id = 3302; id <= 3313; id++) {
      this.orderedEventBetTypeItems.push(this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === id));
    }
  }

  addOrRemoveItemToSelection(eventBetTypeItem: SelectableEventBetTypeItem) {
    this.selectionChanged.emit(eventBetTypeItem);
  }
}
