import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DestroySubject } from '@honoregaming/core';
import { finalize } from 'rxjs/operators';
import { Team } from '../../models/instant-league-ranking-response.model';
import { InstantLeagueService } from '../../services/instant-league.service';
import { MatchState } from '../../models/instant-league-ranking-response.model';

@Component({
  selector: 'hg-instant-league-ranking',
  templateUrl: './instant-league-ranking.component.html',
  styleUrls: ['./instant-league-ranking.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantLeagueRankingComponent extends DestroySubject implements OnInit {
  loading = false;
  error = false;
  MatchState = MatchState;
  entryPointId: number;
  teams: Team[] = [];

  constructor(
    private instantLeagueService: InstantLeagueService,
    private route: ActivatedRoute,
    private cdRef: ChangeDetectorRef
  ) {
    super();
    this.route.params.subscribe(params => {
      this.entryPointId = +params.eventCategoryId;
    });
  }

  ngOnInit() {
    this.loading = true;
    this.error = false;
    this.instantLeagueService
      .getLeagueRanking(this.entryPointId)
      .pipe(
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        result => {
          this.teams = result.teams;
        },
        _ => {
          this.error = true;
        }
      );
  }
}
