import {
  EventBetType,
  Runner,
  BetCategoryType,
  EventBetTypeItem,
  EventWithEventBetTypes,
  SelectableRunner,
  Race,
  Event
} from '@honoregaming/types';
import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  Inject,
  Input,
  OnDestroy,
  Output,
  EventEmitter,
  PLATFORM_ID,
  NgZone
} from '@angular/core';
import { EventsService } from '@honoregaming/events';
import { finalize, takeUntil } from 'rxjs/operators';
import {
  DestroySubject,
  getUtcNow,
  navigationServiceToken,
  INavigationService,
  delayBetween,
  ApplicationStateService,
  generateCombinations,
  getCombinationsMultiplier,
  OddsPreviewerVisibilityService
} from '@honoregaming/core';
import { createBetLineWithSelection, BetSlipService } from '@honoregaming/betslip';
import { VirtualRaceService } from '../../services';
import { isPlatformBrowser } from '@angular/common';
import { merge, Subject } from 'rxjs';
import { OddsPreviewerState } from '@honoregaming/ui';

@Component({
  selector: 'hg-runners',
  templateUrl: './runners.component.html',
  styleUrls: ['./runners.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RunnersComponent extends DestroySubject implements OnInit, OnDestroy {
  public isLoading: boolean;
  public error = false;

  @Input()
  public eventId: number;

  @Input()
  public eventBetTypeId: number;

  @Input()
  public handleNumberPickerInputClick: boolean;

  @Input()
  public numberPickerInputClickHandler: () => any;

  @Output()
  public goBack = new EventEmitter<{ event: Event; isExpired: boolean }>();

  private selectionMode: 'Any' | 'AlreadySelected' = 'Any';

  oddsDestroy$: Subject<boolean> = new Subject<boolean>();

  event: EventWithEventBetTypes<Race>;

  public eventBetType: EventBetType;
  public selection: number[] = [];
  public combinations: { baseList: string[]; fixedOdds: number }[];
  public odds = 0;

  public winnerEventBetTypeItems: EventBetTypeItem[];
  public isEventExpired = false;
  public allOrders = false;
  public betAmount: number;
  public minOdds: number;
  public maxOdds: number;
  public oddsPreviewerState: OddsPreviewerState;
  public isLoadingOdds: boolean;
  public allowedBetTypeForCombination = [30003, 30004, 30005, 30006];
  private oldEventCleanTimer: any;
  public runners = new Array<RunnerWithOdds & { index?: number }>();
  getCombinationsMultiplier = getCombinationsMultiplier;

  constructor(
    private eventsService: EventsService,
    private oddsPreviewerVisibilityService: OddsPreviewerVisibilityService,
    private virtualRaceService: VirtualRaceService,
    private betSlipService: BetSlipService,
    @Inject(PLATFORM_ID) private platformId,
    private zone: NgZone,
    private applicationStateService: ApplicationStateService,
    private cdRef: ChangeDetectorRef,
    @Inject(navigationServiceToken) private navigationService: INavigationService
  ) {
    super();
  }

  ngOnInit(): void {
    this.isLoading = true;

    this.eventsService
      .getEventDetails(this.eventId)
      .pipe(
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        e => {
          if (getUtcNow() >= new Date(e.expectedStart)) {
            this.isEventExpired = true;
          } else {
            this.event = e;
            this.eventBetType = e.eventBetTypes?.find(ebt => ebt.id === this.eventBetTypeId);
            this.winnerEventBetTypeItems = this.event.eventBetTypes?.find(
              ebt => ebt.betTypeId === 30001
            )?.eventBetTypeItems;
            this.betAmount = this.eventBetType?.baseAmount;

            const runners = !this.runners.length ? this.event.runners : this.runners;
            runners.forEach((r, i) => {
              this.runners[i] = { ...r, odds: this.winnerEventBetTypeItems.find(ebti => ebti.runnerId === r.id)?.odds };
            });
            if (isPlatformBrowser(this.platformId)) {
              this.applicationStateService.isReady$.subscribe(() => {
                this.disableEventWhenExpired();
              });
            }
          }
        },
        _ => {
          this.error = true;
        }
      );

    this.navigationService.goBack$.pipe(takeUntil(this.destroy$)).subscribe(_ => {
      if (this.goBack) {
        this.goBack.emit({ event: this.event, isExpired: this.isEventExpired });
      }
    });

    this.virtualRaceService.resetSelectedItems$.pipe(takeUntil(this.destroy$)).subscribe(_ => {
      this.runners.forEach(runner => {
        runner.selected = false;
      });
    });

    if (this.runners) {
      this.runners.forEach(r => (r.selected = false));
    }
  }

  ngOnDestroy() {
    super.ngOnDestroy();

    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(OddsPreviewerState.Closed);

    if (this.oldEventCleanTimer) {
      clearTimeout(this.oldEventCleanTimer);
    }
  }

  private disableEventWhenExpired(): void {
    this.oldEventCleanTimer = setTimeout(() => {
      if (this.oldEventCleanTimer) {
        clearTimeout(this.oldEventCleanTimer);
      }

      this.isEventExpired = true;
      this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(OddsPreviewerState.Closed);
      this.zone.run(() => this.cdRef.markForCheck());
    }, delayBetween(getUtcNow(), new Date(this.event.expectedStart)));
  }

  public onAllOrdersChange() {
    if (this.allOrders) {
      this.selectionMode =
        this.selection.length ===
        Math.min(this.runners.length - 1, this.eventBetType.designationConfiguration.base.maxNumberOfItems)
          ? 'AlreadySelected'
          : 'Any';
    } else {
      if (this.selection.length > this.eventBetType.designationConfiguration.base.minNumberOfItems) {
        this.reset();
      } else {
        this.selectionMode =
          this.selection.length === this.eventBetType.designationConfiguration.base.minNumberOfItems
            ? 'AlreadySelected'
            : 'Any';
      }
    }
    this.computeOdds();
  }

  onSelectionChanged(runner: SelectableRunner) {
    if (this.selectionMode === 'Any') {
      runner.selected = !runner.selected;
    } else {
      if (runner.selected) {
        runner.selected = !runner.selected;
      }
    }

    const index = this.selection.indexOf(runner.number, 0);

    if (runner.selected && index === -1) {
      this.selection.push(runner.number);
    } else {
      if (index > -1) {
        this.selection.splice(index, 1);
      }
    }

    this.manageOddsPreviewerVisibility();
    this.computeOdds();
  }

  private manageOddsPreviewerVisibility(): void {
    this.oddsPreviewerState =
      this.selection?.length > 0 ? OddsPreviewerState.SelectionStakesOpened : OddsPreviewerState.Closed;
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(this.oddsPreviewerState);
  }

  private computeOdds(): void {
    if (
      this.selection.length >= this.eventBetType.designationConfiguration.base.minNumberOfItems &&
      this.selection.length <=
        Math.min(this.runners.length - 1, this.eventBetType.designationConfiguration.base.maxNumberOfItems)
    ) {
      this.oddsDestroy$.next(true);

      this.isLoadingOdds = true;
      if (
        this.selection.length > this.eventBetType.designationConfiguration.base.minNumberOfItems ||
        (this.selection.length === this.eventBetType.designationConfiguration.base.minNumberOfItems && this.allOrders)
      ) {
        const combi = generateCombinations(
          this.selection,
          this.eventBetType.designationConfiguration.base.minNumberOfItems,
          this.allOrders
        ).map(x => x.join('-'));
        this.eventsService
          .getOddsForDesignations(this.event.id, this.eventBetType.id, combi)
          .pipe(takeUntil(merge(this.oddsDestroy$, this.destroy$)))
          .subscribe(combinations => {
            this.odds = null;
            const oldMinStake = this.eventBetType.baseAmount * getCombinationsMultiplier(this.combinations);
            this.combinations = combinations;
            this.isLoadingOdds = false;
            const odds = this.combinations.map(x => x.fixedOdds);
            this.minOdds = Math.min(...odds);
            this.maxOdds = Math.max(...odds);
            const minStake = this.eventBetType.baseAmount * getCombinationsMultiplier(combinations);
            this.betAmount = this.betAmount > minStake && this.betAmount !== oldMinStake ? this.betAmount : minStake;
            this.cdRef.markForCheck();
          });
      } else {
        this.eventsService
          .getOddsForDesignation(this.event.id, this.eventBetType.id, this.selection.map(s => s).join('-'))
          .pipe(takeUntil(merge(this.oddsDestroy$, this.destroy$)))
          .subscribe(odds => {
            this.odds = odds;
            const oldMinStake = this.eventBetType.baseAmount * getCombinationsMultiplier(this.combinations);
            this.combinations = null;
            this.betAmount =
              this.betAmount > this.eventBetType.baseAmount && this.betAmount !== oldMinStake
                ? this.betAmount
                : this.eventBetType.baseAmount;
            this.isLoadingOdds = false;
            this.cdRef.markForCheck();
          });
      }

      if (
        this.selection.length ===
          Math.min(this.runners.length - 1, this.eventBetType.designationConfiguration.base.maxNumberOfItems) ||
        (!this.eventBetType.designationConfiguration.isOrdered &&
          !this.allOrders &&
          this.selection.length >= this.eventBetType.designationConfiguration.base.minNumberOfItems)
      ) {
        this.selectionMode = 'AlreadySelected';
      } else {
        this.selectionMode = 'Any';
      }
    } else {
      this.odds = 0;
      this.minOdds = null;
      this.maxOdds = null;
      this.selectionMode = 'Any';
    }
  }

  public addToBetslip(): void {
    const betLine = createBetLineWithSelection(
      this.event,
      this.eventBetType,
      this.selection.map(s => s.toString()),
      null,
      BetCategoryType.VirtualFixedOdds,
      null,
      this.odds,
      this.combinations
    );
    this.betSlipService.addBetLine(betLine);
    if (this.betAmount > 0) {
      this.betSlipService.updateBetLine(betLine, this.betAmount);
    }

    this.reset();
    this.manageOddsPreviewerVisibility();
  }

  private reset(): void {
    this.betAmount = this.eventBetType?.baseAmount;
    this.selectionMode = 'Any';
    this.minOdds = null;
    this.maxOdds = null;
    this.selection = [];
    this.odds = 0;
    this.virtualRaceService.resetSelectedItems();
  }

  trackBy(_index: number, runner: Runner) {
    return runner.number;
  }
}

export interface RunnerWithOdds extends SelectableRunner {
  odds: number;
}
