import { Component, ChangeDetectionStrategy, Input } from '@angular/core';
import { LuckyLootItemColor } from '@honoregaming/types';
import { LuckyLootItemBackgroundColors, LuckyLootItemInputColors } from '../../../constants/lucky-loot-item';

@Component({
  selector: 'hg-lucky-loot-item',
  templateUrl: './lucky-loot-item.component.html',
  styleUrls: ['./lucky-loot-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LuckyLootItemComponent {
  @Input()
  number: number;

  @Input()
  color: LuckyLootItemColor;

  @Input()
  selected: boolean;

  @Input()
  allSelected: boolean;

  LuckyLootItemBackgroundColors = LuckyLootItemBackgroundColors;
  LuckyLootItemInputColors = LuckyLootItemInputColors;
}
