import {
  Component,
  ChangeDetectionStrategy,
  AfterViewInit,
  Input,
  ViewChild,
  ElementRef,
  EventEmitter,
  Output,
  OnChanges,
  OnDestroy,
  Inject,
  OnInit
} from '@angular/core';
import { OddsPreviewerState, RouletteItemSize } from '@honoregaming/ui';
import {
  SelectableEventBetTypeItem,
  EventBetType,
  EventBetTypeItem,
  SpinAndWinSelectionMode
} from '@honoregaming/types';
import { OddsPreviewerVisibilityService, Scope, scopeToken } from '@honoregaming/core';
import { operatorConfigurationToken } from '@honoregaming/configuration';
import { AgentOperatorConfiguration } from '@honoregaming/agent-core';

@Component({
  selector: 'hg-spin-and-win-neighbors',
  templateUrl: './spin-and-win-neighbors.component.html',
  styleUrls: ['./spin-and-win-neighbors.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinNeighborsComponent implements OnInit, AfterViewInit, OnChanges, OnDestroy {
  @Input() eventBetType!: EventBetType;
  @Input() eventBetTypeItems!: SelectableEventBetTypeItem[];

  @Output() selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  @ViewChild('input') input?: ElementRef;

  readonly SpinAndWinSelectionMode = SpinAndWinSelectionMode;
  readonly RouletteItemSize = RouletteItemSize;
  readonly items = Array.from({ length: 37 }, (_, i) => i);

  enableSpinAndWinGridSelectionMode: boolean =
    this.agentOperatorConfiguration?.retailConfiguration?.enableSpinAndWinGridSelectionMode;

  selectionMode: SpinAndWinSelectionMode = SpinAndWinSelectionMode.Manual;
  orderedEventBetTypeItems: SelectableEventBetTypeItem[] = [];
  oddsPreviewerState?: OddsPreviewerState;
  eventBetTypeItem?: EventBetTypeItem;
  selected?: number;
  stakes?: number;

  constructor(
    private readonly oddsPreviewerVisibilityService: OddsPreviewerVisibilityService,
    @Inject(operatorConfigurationToken) private readonly agentOperatorConfiguration: AgentOperatorConfiguration,
    @Inject(scopeToken) public readonly scope: Scope
  ) {}

  ngOnInit(): void {
    this.initializeGridSelectionMode();
  }

  ngAfterViewInit(): void {
    this.stakes = this.eventBetType.baseAmount;
    this.input.nativeElement.focus();
  }

  ngOnChanges(): void {
    this.orderedEventBetTypeItems = [];
    for (let id = 3318; id <= 3354; id++) {
      this.orderedEventBetTypeItems.push(this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === id));
    }
  }

  ngOnDestroy(): void {
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(OddsPreviewerState.Closed);
  }

  previewSelectedItem(): void {
    this.eventBetTypeItem = this.orderedEventBetTypeItems[this.selected];
    this.oddsPreviewerState = this.eventBetTypeItem
      ? OddsPreviewerState.SelectionStakesOpened
      : OddsPreviewerState.Closed;
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(this.oddsPreviewerState);
  }

  addOrRemoveItemToSelection(): void {
    this.selectionChanged.emit(this.eventBetTypeItem);
    this.selected = null;
    this.previewSelectedItem();
  }

  selectItem(item: number): void {
    this.selected = item;
    this.previewSelectedItem();
  }

  trackByIndex(index: number): number {
    return index;
  }

  private initializeGridSelectionMode(): void {
    const isAgentWithGridEnabled: boolean = this.enableSpinAndWinGridSelectionMode && this.scope === Scope.Agent;

    if (isAgentWithGridEnabled) {
      this.selectionMode = SpinAndWinSelectionMode.Grid;
    }
  }

  // tslint:disable-next-line: member-ordering
  spinAndWinNeighbors: { [id: number]: number[] } = {
    0: [3, 26, 0, 32, 15],
    1: [16, 33, 1, 20, 14],
    2: [4, 21, 2, 25, 17],
    3: [12, 35, 3, 26, 0],
    4: [15, 19, 4, 21, 2],
    5: [23, 10, 5, 24, 16],
    6: [17, 34, 6, 27, 13],
    7: [18, 29, 7, 28, 12],
    8: [11, 30, 8, 23, 10],
    9: [14, 31, 9, 22, 18],
    10: [8, 23, 10, 5, 24],
    11: [13, 36, 11, 30, 8],
    12: [7, 28, 12, 35, 3],
    13: [6, 27, 13, 36, 11],
    14: [1, 20, 14, 31, 9],
    15: [0, 32, 15, 19, 4],
    16: [5, 24, 16, 33, 1],
    17: [2, 25, 17, 34, 6],
    18: [9, 22, 18, 29, 7],
    19: [32, 15, 19, 4, 21],
    20: [33, 1, 20, 14, 31],
    21: [19, 4, 21, 2, 25],
    22: [31, 9, 22, 18, 29],
    23: [30, 8, 23, 10, 5],
    24: [10, 5, 24, 16, 33],
    25: [21, 2, 25, 17, 34],
    26: [35, 3, 26, 0, 32],
    27: [34, 6, 27, 13, 36],
    28: [29, 7, 28, 12, 35],
    29: [22, 18, 29, 7, 28],
    30: [36, 11, 30, 8, 23],
    31: [20, 14, 31, 9, 22],
    32: [26, 0, 32, 15, 19],
    33: [24, 16, 33, 1, 20],
    34: [25, 17, 34, 6, 27],
    35: [28, 12, 35, 3, 26],
    36: [27, 13, 36, 11, 30]
  };
}
