import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { globalConfiguration } from '@honoregaming/configuration';
import { QueryBuilderService } from 'projects/core/hg-core/src/lib/services/query-builder.service';
import { Observable } from 'rxjs';
import { InstantLeagueMatchesResponse } from '../models/instant-league-matches-response.model';
import { InstantLeagueRankingResponse } from '../models/instant-league-ranking-response.model';
import { InstantLeagueResultsResponse } from '../models/instant-league-results-response.model';
import { InstantLeagueRoundResponse } from '../models/instant-league-round-response.model';
import { InstantLeagueRound } from '../models/instant-league-round.model';

@Injectable({ providedIn: 'root' })
export class InstantLeagueService {
  constructor(private httpClient: HttpClient, private queryBuilder: QueryBuilderService) {}

  getLeagueRanking(parentEventCategoryId: number): Observable<InstantLeagueRankingResponse> {
    return this.httpClient.get<InstantLeagueRankingResponse>(
      `${globalConfiguration.apiEventsBaseUrl}instantleagues/${parentEventCategoryId}/ranking`
    );
  }

  getLeagueResults(
    parentEventCategoryId: number,
    skip: number,
    take: number
  ): Observable<InstantLeagueResultsResponse> {
    var queryString = this.queryBuilder.buildHttpParams({
      skip: skip,
      take: take
    });
    return this.httpClient.get<InstantLeagueResultsResponse>(
      `${globalConfiguration.apiEventsBaseUrl}instantleagues/${parentEventCategoryId}/results`,
      {
        params: queryString
      }
    );
  }

  getLeagueMatches(parentEventCategoryId: number): Observable<InstantLeagueMatchesResponse> {
    return this.httpClient.get<InstantLeagueMatchesResponse>(
      `${globalConfiguration.apiEventsBaseUrl}instantleagues/${parentEventCategoryId}/matches`
    );
  }

  getRoundPlayout(
    parentEventCategoryId: number,
    eventCategoryId: number,
    roundId: number
  ): Observable<InstantLeagueRound> {
    var queryString = this.queryBuilder.buildHttpParams({
      eventCategoryId: eventCategoryId,
      parentEventCategoryId: parentEventCategoryId
    });
    return this.httpClient.get<InstantLeagueRound>(
      `${globalConfiguration.apiEventsBaseUrl}instantleagues/round/${roundId}/playout`,
      {
        params: queryString
      }
    );
  }

  getRound(eventCategoryId: number, roundId: number, getNext = false): Observable<InstantLeagueRoundResponse> {
    var queryString = this.queryBuilder.buildHttpParams({
      eventCategoryId: eventCategoryId,
      getNext: getNext
    });

    return this.httpClient.get<InstantLeagueRoundResponse>(
      `${globalConfiguration.apiEventsBaseUrl}instantleagues/round/${roundId}`,
      {
        params: queryString
      }
    );
  }
}
