import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnInit,
  HostBinding,
  Inject,
  PLATFORM_ID,
  Input,
  SimpleChanges,
  OnChanges
} from '@angular/core';
import { EventCategoriesNavigationComponent } from '../event-categories-navigation.component';
import { EventCategoriesService } from '@honoregaming/events';
import { ActivatedRoute, Router } from '@angular/router';
import { scopeToken, Scope } from '@honoregaming/core';
import { isPlatformServer } from '@angular/common';
import { CategoriesLeagueEnum, FootballLeagueEnum, InsaLeagueEnum } from '@honoregaming/types';
import { RaceEnum } from '../../../enums/races.enum';
import { GamesEnum } from '../../../enums/games.enum';
import { VirtualRaceService } from '../../../services';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Component({
  selector: 'hg-virtual-mobile-event-categories-navigation',
  templateUrl: './event-categories-navigation.component.html',
  styleUrls: ['./event-categories-navigation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MobileNavigationEventCategoriesNavigationComponent
  extends EventCategoriesNavigationComponent
  implements OnInit, OnChanges
{
  @HostBinding('class') class = 'desktop-navigation-menu';

  @Input() eventCategoryId: number;

  index: number;
  footballLeagueEnum = FootballLeagueEnum;
  insaLeagueEnum = InsaLeagueEnum;
  racesEnum = RaceEnum;
  gamesEnum = GamesEnum;

  category: any;

  isServer = isPlatformServer(this.platformId);

  displayBetCategoryNameOnMobile = this.operatorConfiguration.onlineConfiguration?.showBetCategoryNameOnMobile;
  displayEntryPointsMenu = !this.operatorConfiguration.onlineConfiguration?.displayVirtualHome;

  constructor(
    route: ActivatedRoute,
    router: Router,
    virtualRaceService: VirtualRaceService,
    eventCategoriesService: EventCategoriesService,
    @Inject(PLATFORM_ID) private platformId,
    cdRef: ChangeDetectorRef,
    @Inject(scopeToken) public scope: Scope,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration
  ) {
    super(route, router, eventCategoriesService, virtualRaceService, cdRef, scope);
  }

  ngOnInit() {
    super.ngOnInit();
    this.cdRef.markForCheck();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (
      changes.eventCategoryId?.currentValue ||
      changes.currentIndex?.currentValue ||
      changes.eventCategoryId?.currentValue === 0
    ) {
      this.clickOnCategory(this.eventCategoryId);
    }

    this.cdRef.detectChanges();
  }

  categoryCountryName(name: string) {
    const categoriesArray = Object.values(CategoriesLeagueEnum);
    for (let i = 0; i < categoriesArray.length; i++) {
      const category = categoriesArray[i];
      if (name.match(new RegExp(`\\b${category}\\b`))) {
        return name.match(new RegExp(`\\b${category}\\b`))[0];
      }
    }

    return name;
  }

  getCategoryIcon(entrypoint: any) {
    if (InsaLeagueEnum[entrypoint.id]) {
      return 'url(/assets/virtual/' + entrypoint.id + '.png)';
    }

    return 'url(/assets/virtual/' + this.categoryCountryName(entrypoint.name).toLowerCase() + '.png)';
  }

  clickOnCategory(entrypoint: number) {
    this.category = this.instantLeague.includes(entrypoint)
      ? this.InstantLeagueEnum
      : this.insaLeague.includes(entrypoint)
      ? this.insaLeagueEnum
      : this.footballLeague.includes(entrypoint)
      ? this.footballLeagueEnum
      : this.races.includes(entrypoint)
      ? this.racesEnum
      : this.games.includes(entrypoint)
      ? this.gamesEnum
      : undefined;
    this.cdRef.markForCheck();
  }
}
