import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { EventWithEventBetTypes, Event, EventType, SelectableEventBetTypeItem } from '@honoregaming/types';

@Component({
  selector: 'hg-spin-and-win-event-bet-types',
  templateUrl: './spin-and-win-event-bet-types.component.html',
  styleUrls: ['./spin-and-win-event-bet-types.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinEventBetTypesComponent {
  @Input()
  public event: EventWithEventBetTypes<Event>;

  @Output()
  public betSelectionChanged = new EventEmitter<{
    item: SelectableEventBetTypeItem;
    selected: boolean;
  }>();

  public EventType = EventType;

  toggleBet(item) {
    if (
      !item.odds ||
      item.odds <= 1 ||
      !item.active ||
      !item.bettingAllowed ||
      !this.event.eventBetTypes[0].active ||
      !this.event.eventBetTypes[0].bettingAllowed
    ) {
      return;
    }

    this.betSelectionChanged.emit({
      item: item,
      selected: !item.selected
    });
  }
}
