import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { EventStateType, EventCategoryWithStreamConfiguration, EventCategory } from '@honoregaming/types';
import { EventCategoriesService } from '@honoregaming/events';
import { DestroySubject } from '@honoregaming/core';
import { skip, takeUntil } from 'rxjs/operators';
import { merge } from 'rxjs';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-eventcategory-layout',
  templateUrl: './eventcategory-layout.component.html',
  styleUrls: ['./eventcategory-layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventCategoryLayoutComponent extends DestroySubject implements OnInit {
  eventCategoryId: number;

  EventStateType = EventStateType;
  eventCategory: EventCategoryWithStreamConfiguration;
  loading = false;
  videoPlayerShouldBeOpenedByDefault: boolean =
    this.operatorConfiguration.onlineConfiguration?.openVirtualStreamingPlayerOnMobile ?? false;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private cdRef: ChangeDetectorRef,
    private eventCategoriesService: EventCategoriesService,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      if (this.eventCategoryId !== +params['eventCategoryId']) {
        this.loading = true;
        this.eventCategoryId = +params['eventCategoryId'];
        this.eventCategoriesService
          .getEventCategory(this.eventCategoryId)
          .pipe(takeUntil(merge(this.route.params.pipe(skip(1)), this.destroy$)))
          .subscribe(
            e => {
              this.eventCategory = e;

              this.loading = false;
              this.cdRef.markForCheck();
            },
            e => {
              if (e.status === 404) {
                this.router.navigate(['/virtual']);
              }
            }
          );
      }
    });
  }

  getEventCategoryName(eventCategory: EventCategory): string {
    return this.i18nService.translateWithFallbackSync(
      'VIRTUAL.FOOTBALL_LEAGUE.' + eventCategory.id + '.NAME',
      eventCategory.name
    );
  }
}
