import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  ChangeDetectorRef,
  OnChanges,
  Inject,
  Optional
} from '@angular/core';
import { AuthService } from '@honoregaming/customer-core';
import { takeUntil } from 'rxjs/operators';
import { DestroySubject, DialogService } from '@honoregaming/core';
import { StreamConfiguration, DisplayMode } from '@honoregaming/types';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Media, MediaService, MessageService, WarningDataComponent } from '@honoregaming/ui';

@Component({
  selector: 'hg-video-player',
  templateUrl: './video-player.component.html',
  styleUrls: ['./video-player.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class VideoPlayerComponent extends DestroySubject implements OnInit, OnChanges {
  @Input()
  public streamConfig: StreamConfiguration;
  @Input()
  public shouldBeOpenedByDefault: boolean;

  public DisplayMode = DisplayMode;
  public isIFrameVisible: boolean;
  public isUserLoggedIn: boolean;

  public isClosed: boolean;
  media: Media;

  warnOnDataConsumption = this.operatorConfiguration.onlineConfiguration?.warnOnDataConsumption;
  constructor(
    private authService: AuthService,
    private messageService: MessageService,
    private dialogService: DialogService,
    private cdRef: ChangeDetectorRef,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    @Optional() private mediaService: MediaService
  ) {
    super();
  }

  ngOnInit() {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.isUserLoggedIn = !!me;
      this.cdRef.markForCheck();
    });
    if (this.warnOnDataConsumption) {
      this.closeVideoPlayer();
    }

    this.mediaService?.media$.subscribe(x => {
      x < Media.lg ? (this.isClosed = true) : (this.isClosed = false);
      this.cdRef.markForCheck();
    });

    if (this.shouldBeOpenedByDefault) {
      this.openVideoPlayer();
    }
  }

  ngOnChanges(): void {
    if (this.isIFrameVisible && this.streamConfig) {
      this.isIFrameVisible = false;
      this.cdRef.markForCheck();
    }
  }

  public connect(): void {
    this.dialogService.toggleDialog('login', true);
  }

  public closeVideoPlayer(): void {
    this.isClosed = true;
    this.isIFrameVisible = false;
  }

  public openVideoPlayer(): void {
    if (this.shouldBeOpenedByDefault) {
      this.isIFrameVisible = false;
      this.isClosed = false;
    } else {
      if (this.warnOnDataConsumption) {
        this.messageService
          .sendComponentMessage(
            WarningDataComponent,
            {
              messageKey: 'WARN.DATA.STREAMING'
            },
            { queue: true },
            this.destroy$,
            true
          )
          .closed.subscribe(result => {
            if (!result) {
              return;
            }
            this.isIFrameVisible = false;
            this.isClosed = false;
            this.cdRef.markForCheck();
          });
      } else {
        this.isIFrameVisible = false;
        this.isClosed = false;
      }
    }
  }

  public showIFrame(): void {
    this.isIFrameVisible = true;
  }
}
