import { filter, skip, take, takeUntil } from 'rxjs/operators';
import { EventEmitter, Output, OnInit, ChangeDetectorRef, Directive, Inject } from '@angular/core';
import { EventCategoriesService } from '@honoregaming/events';
import { EventCategory, FootballLeagueEnum, InsaLeagueEnum, InstantLeagueEnum } from '@honoregaming/types';
import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
import { DestroySubject, Scope, scopeToken } from '@honoregaming/core';
import { merge } from 'rxjs';
import { RaceEnum } from '../../enums/races.enum';
import { GamesEnum } from '../../enums/games.enum';
import { VirtualRaceService } from '../../services';

@Directive()
// tslint:disable-next-line: directive-class-suffix
export class EventCategoriesNavigationComponent extends DestroySubject implements OnInit {
  @Output()
  public navigated = new EventEmitter<number>();

  @Output()
  toggleMenuEvent = new EventEmitter<void>();

  @Output() entryPointIndex = new EventEmitter<number>();

  loading = false;
  entryPoints: EventCategory[];
  currentEntryPoint: EventCategory;
  currentIndex: number;

  InsaLeagueEnum = InsaLeagueEnum;
  InstantLeagueEnum = InstantLeagueEnum;
  instantLeague = Object.values(InstantLeagueEnum);
  insaLeague = Object.values(InsaLeagueEnum);
  footballLeague = Object.values(FootballLeagueEnum);
  races = Object.values(RaceEnum);
  games = Object.values(GamesEnum);

  entryPointsFilter = [];

  Scope = Scope;
  defaultIndex: number;
  hasCurrentIndex: boolean;

  constructor(
    public route: ActivatedRoute,
    private router: Router,
    private eventCategoriesService: EventCategoriesService,
    private virtualRaceService: VirtualRaceService,
    public cdRef: ChangeDetectorRef,
    @Inject(scopeToken) public scope: Scope
  ) {
    super();
  }

  ngOnInit() {
    if (!this.currentIndex) {
      this.router.events.pipe(filter(x => x instanceof NavigationEnd)).subscribe(() => {
        let currentId = this.router.routerState.snapshot.url.replace(/[^0-9]/g, '');
        this.virtualRaceService.clickNextVirtual(currentId);
        this.currentIndex = Number(currentId);
        if (this.currentIndex === 0) {
          this.entryPointIndex.emit(0);
        }
      });
    }

    this.loading = true;
    // 5 is for Virtual
    this.eventCategoriesService
      .getEntryPointsForRootEventCategories([5])
      .pipe(takeUntil(this.destroy$))
      .subscribe((entryPoints: EventCategory[]) => {
        this.entryPoints = entryPoints;
        const arrayEntrypoints = this.entryPoints.map(e => e.id);
        this.checkIfEntrypointsExist(arrayEntrypoints);

        this.router.events
          .pipe(
            filter(event => event instanceof NavigationEnd),
            take(1)
          )
          .subscribe(() => {
            this.defaultIndex = this.currentIndex;
            this.checkIfEntrypointsExist(arrayEntrypoints);
          });

        this.virtualRaceService.displayNextVirtual.pipe(takeUntil(this.destroy$)).subscribe(() => {
          this.entryPointsFilter = [];
          this.checkIfEntrypointsExist(arrayEntrypoints);
        });

        this.currentIndex === undefined ? (this.hasCurrentIndex = true) : (this.hasCurrentIndex = false);

        this.route.params.pipe(takeUntil(merge(this.route.params.pipe(skip(1)), this.destroy$))).subscribe(params => {
          if (this.entryPoints && this.entryPoints.length > 0 && params['eventCategory']) {
            this.currentEntryPoint = this.entryPoints.find(e => e.id === +params['eventCategory']);
          }
          this.loading = false;
          this.cdRef.markForCheck();
        });
        this.loading = false;
        this.cdRef.markForCheck();
      });
  }

  checkIfEntrypointsExist(entryPoints: number[]) {
    let instantLeagueArray = entryPoints.filter(e => this.instantLeague.includes(e));
    let insaLeagueArray = entryPoints.filter(e => this.insaLeague.includes(e));
    let fastLeagueArray = entryPoints.filter(e => this.footballLeague.includes(e));
    let racesArray = entryPoints.filter(e => this.races.includes(e));
    let gamesArray = entryPoints.filter(e => this.games.includes(e));
    let route = this.route.snapshot['_routerState'].url;
    if (instantLeagueArray.map(String).some(a => route.includes(a))) {
      this.currentIndex = instantLeagueArray[0];
    } else if (insaLeagueArray.map(String).some(a => route.includes(a))) {
      this.currentIndex = insaLeagueArray[0];
    } else if (fastLeagueArray.map(String).some(a => route.includes(a))) {
      this.currentIndex = fastLeagueArray[0];
    } else if (racesArray.map(String).some(a => route.includes(a))) {
      this.currentIndex = racesArray[0];
    } else if (gamesArray.map(String).some(a => route.includes(a))) {
      this.currentIndex = gamesArray[0];
    }

    let filters = [instantLeagueArray[0], insaLeagueArray[0], fastLeagueArray[0], racesArray[0], gamesArray[0]];

    if (this.defaultIndex !== undefined && this.hasCurrentIndex) {
      filters.unshift(this.defaultIndex);
    }

    this.entryPointsFilter = Array.from(new Set(filters)).filter(e => e !== undefined);

    if (this.defaultIndex !== undefined && this.hasCurrentIndex) {
      const otherFilters = this.entryPointsFilter.filter(e => e !== this.defaultIndex);
      this.entryPointsFilter = [this.defaultIndex, ...otherFilters];
    } else {
      this.defaultIndex = this.entryPointsFilter[0];
    }

    this.entryPointIndex.emit(this.currentIndex);
    this.cdRef.markForCheck();
  }

  onMenuClickAction() {
    this.toggleMenuEvent.emit();
  }
}
