import {
  ChangeDetectionStrategy,
  Component,
  ChangeDetectorRef,
  OnInit,
  OnDestroy,
  Optional,
  Inject
} from '@angular/core';
import { BetSlipService } from '@honoregaming/betslip';
import { EventCategoriesService, EventsMapperService } from '@honoregaming/events';
import { Media, MediaService } from '@honoregaming/ui';
import { trigger, transition, animate, style } from '@angular/animations';
import { EventWithEventBetTypeBaseComponent } from '../../event-with-eventbettype.basecomponent';
import { takeUntil } from 'rxjs/operators';
import {
  EventCategory,
  CategoriesLeagueEnum,
  FootballLeagueEnum,
  InsaLeagueEnum,
  InstantLeagueEnum,
  isInsaLeaguesEntryPoint
} from '@honoregaming/types';
import { RaceEnum, GamesEnum } from '@honoregaming/virtual-ui';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { Router } from '@angular/router';

@Component({
  selector: 'hg-virtual-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('removed', [
      transition('* => void', [animate('0.1s ease-out', style({ transform: 'scale(0)', height: '0' }))])
    ])
  ]
})
export class HomeComponent extends EventWithEventBetTypeBaseComponent implements OnInit, OnDestroy {
  loading = false;
  entryPoints: EventCategory[];
  instantLeagues: EventCategory[];
  insaLeagues: EventCategory[];
  footballLeagues: EventCategory[];
  games: EventCategory[];
  instantLeaguesNumbersDisplayed: number = 6;
  hasDisplayedAllInstantLeagues: boolean = false;

  InsaLeagueEnum = InsaLeagueEnum;
  InstantLeagueEnum = InstantLeagueEnum;
  instantLeague = Object.values(InstantLeagueEnum);
  insaLeague = Object.values(InsaLeagueEnum);
  footballLeague = Object.values(FootballLeagueEnum);
  Races = Object.values(RaceEnum);
  Games = Object.values(GamesEnum);

  constructor(
    betSlipService: BetSlipService,
    private eventCategoriesService: EventCategoriesService,
    eventsMapperService: EventsMapperService,
    cdRef: ChangeDetectorRef,
    @Optional() private mediaService: MediaService,
    @Inject(customerOperatorConfigurationToken) private customerOperatorConfiguration: CustomerOperatorConfiguration,
    private router: Router
  ) {
    super(betSlipService, eventsMapperService, cdRef);
  }

  ngOnInit() {
    super.ngOnInit();

    this.loading = true;
    this.eventCategoriesService
      .getEntryPointsForRootEventCategories([5])
      .pipe(takeUntil(this.destroy$))
      .subscribe((entryPoints: EventCategory[]) => {
        this.entryPoints = entryPoints;
        if (!this.customerOperatorConfiguration.onlineConfiguration?.displayVirtualHome) {
          this.redirectFirstEntryPoint();
          return;
        }
        this.instantLeagues = entryPoints.filter(e => this.instantLeague.includes(e.id));
        this.insaLeagues = entryPoints.filter(e => this.insaLeague.includes(e.id));
        this.footballLeagues = entryPoints.filter(e => this.footballLeague.includes(e.id));
        this.games = entryPoints.filter(e => this.Games.includes(e.id) || this.Races.includes(e.id));
        this.loading = false;
        this.cdRef.markForCheck();
      });
    if (this.mediaService.media > Media.md) {
      this.instantLeaguesNumbersDisplayed = 4;
    }
  }

  getCategoryIcon(entrypoint: any) {
    if (InsaLeagueEnum[entrypoint.id]) {
      return 'url(/assets/virtual/' + entrypoint.id + '.png)';
    }

    return 'url(/assets/virtual/' + this.categoryCountryName(entrypoint.name).toLowerCase() + '.png)';
  }

  categoryCountryName(name: string) {
    const categoriesArray = Object.values(CategoriesLeagueEnum);
    for (let i = 0; i < categoriesArray.length; i++) {
      const category = categoriesArray[i];
      if (name.match(new RegExp(`\\b${category}\\b`))) {
        return name.match(new RegExp(`\\b${category}\\b`))[0];
      }
    }

    return name;
  }

  redirectFirstEntryPoint() {
    const ep = this.entryPoints.filter(ep => ep.parentEventCategoryId === 5).sort((a, b) => a.priority - b.priority);
    if (ep?.length) {
      var eventCategoryId = ep[0].id;
      if (isInsaLeaguesEntryPoint(eventCategoryId)) {
        this.router.navigate(['/virtual/category/instant-league', eventCategoryId]);
      } else {
        this.router.navigate(['/virtual/category', eventCategoryId]);
      }
    }
  }
}
