import {
  Component,
  ChangeDetectionStrategy,
  Input,
  ViewChild,
  ElementRef,
  AfterViewInit,
  Output,
  EventEmitter,
  OnDestroy,
  Inject,
  OnInit,
  HostBinding
} from '@angular/core';
import { OddsPreviewerState, RouletteItemSize } from '@honoregaming/ui';
import {
  SelectableEventBetTypeItem,
  EventBetType,
  EventBetTypeItem,
  SpinAndWinSelectionMode
} from '@honoregaming/types';
import { OddsPreviewerVisibilityService, Scope, scopeToken } from '@honoregaming/core';
import { operatorConfigurationToken } from '@honoregaming/configuration';
import { AgentOperatorConfiguration } from '@honoregaming/agent-core';

@Component({
  selector: 'hg-spin-and-win-winner',
  templateUrl: './spin-and-win-winner.component.html',
  styleUrls: ['./spin-and-win-winner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinWinnerComponent implements OnInit, AfterViewInit, OnDestroy {
  @Input() eventBetTypeItems!: SelectableEventBetTypeItem[];
  @Input() eventBetType!: EventBetType;

  @Output() selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  @ViewChild('input') input?: ElementRef;

  readonly SpinAndWinSelectionMode = SpinAndWinSelectionMode;
  readonly RouletteItemSize = RouletteItemSize;
  readonly items = Array.from({ length: 37 }, (_, i) => i);

  enableSpinAndWinGridSelectionMode: boolean =
    this.agentOperatorConfiguration?.retailConfiguration?.enableSpinAndWinGridSelectionMode;

  selectionMode: SpinAndWinSelectionMode = SpinAndWinSelectionMode.Manual;
  oddsPreviewerState?: OddsPreviewerState;

  eventBetTypeItem?: EventBetTypeItem;
  selected?: number;
  stakes?: number;

  constructor(
    private readonly oddsPreviewerVisibilityService: OddsPreviewerVisibilityService,
    @Inject(operatorConfigurationToken) private readonly agentOperatorConfiguration: AgentOperatorConfiguration,
    @Inject(scopeToken) public readonly scope: Scope
  ) {}

  ngOnInit(): void {
    this.initializeGridSelectionMode();
  }

  ngAfterViewInit(): void {
    this.stakes = this.eventBetType.baseAmount;
    this.input.nativeElement.focus();
  }

  ngOnDestroy(): void {
    this.updateOddsPreviewerState(OddsPreviewerState.Closed);
  }

  @HostBinding('class.grid')
  get isSelectionModeGrid(): boolean {
    return this.selectionMode === SpinAndWinSelectionMode.Grid;
  }

  addOrRemoveItemToSelection(): void {
    this.eventBetTypeItem = this.findBetTypeItemBySelection(this.selected);

    const state: OddsPreviewerState = this.eventBetTypeItem
      ? OddsPreviewerState.SelectionStakesOpened
      : OddsPreviewerState.Closed;

    this.updateOddsPreviewerState(state);
  }

  selectItem(item: number): void {
    this.selected = item;
    this.addToSelection();
  }

  addToBetslip(): void {
    this.selectionChanged.emit(this.eventBetTypeItem);
    this.selected = null;
    this.addOrRemoveItemToSelection();
  }

  trackByIndex(index: number): number {
    return index;
  }

  private initializeGridSelectionMode(): void {
    const isAgentWithGridEnabled: boolean = this.enableSpinAndWinGridSelectionMode && this.scope === Scope.Agent;

    if (isAgentWithGridEnabled) {
      this.selectionMode = SpinAndWinSelectionMode.Grid;
    }
  }

  private findBetTypeItemBySelection(selection: number): EventBetTypeItem | undefined {
    return this.eventBetTypeItems.find(item => Number.parseInt(item.shortName, 10) === selection);
  }

  private updateOddsPreviewerState(state: OddsPreviewerState): void {
    this.oddsPreviewerState = state;
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(state);
  }

  private addToSelection(): void {
    this.eventBetTypeItem = this.findBetTypeItemBySelection(this.selected);
    this.addToBetslip();
  }
}
