import { happenBefore, getUtcNow, delayBetween } from '@honoregaming/core';
import { Observable } from 'rxjs';

export function eventIsAboutToStart(date: Date, delayInSeconds: number): boolean {
  return happenBefore(getUtcNow(), new Date(date), delayInSeconds * 60000);
}

export function registerForEventIsAboutToStartNotification(
  expectedStart: Date,
  delayBeforeVirtualEventIsGoingLiveInMinutes: number
): Observable<{}> {
  return new Observable(observer => {
    const isAboutToStartTimer = setTimeout(() => {
      clearTimeout(isAboutToStartTimer);

      observer.next();
      // tslint:disable-next-line: max-line-length
    }, delayBetween(getUtcNow(), new Date(new Date(expectedStart).setUTCMinutes(new Date(expectedStart).getUTCMinutes() - delayBeforeVirtualEventIsGoingLiveInMinutes))));
  });
}

export function registerForEventStartsNotification(expectedStart: Date): Observable<{}> {
  return new Observable(observer => {
    const startsTimer = setTimeout(() => {
      clearTimeout(startsTimer);

      observer.next();
      // tslint:disable-next-line: max-line-length
    }, delayBetween(getUtcNow(), new Date(new Date(expectedStart))));
  });
}
