import { DestroySubject } from '@honoregaming/core';
import { OnInit, ChangeDetectorRef, Directive } from '@angular/core';
import { BetSlipService } from '@honoregaming/betslip';
import { EventWithEventBetType, Event } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';
import { EventsMapperService } from '@honoregaming/events';

@Directive()
export class EventWithEventBetTypeBaseComponent extends DestroySubject implements OnInit {
  eventsWithEventBetTypes: EventWithEventBetType<Event>[] = [];
  selectedBets: { eventId: number; betTypeId: number; eventBetTypeItemId: number }[];

  constructor(
    protected betSlipService: BetSlipService,
    protected eventsMapperService: EventsMapperService,
    protected cdRef: ChangeDetectorRef
  ) {
    super();
  }

  ngOnInit() {
    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(event => {
      this.selectedBets = event.lines.map(e => {
        return {
          eventId: e.eventId,
          betTypeId: e.betTypeId,
          eventBetTypeItemId: e.eventBetTypeItemId
        };
      });

      this.eventsMapperService.updateEventsWithEventBetTypesSelectedItems(
        this.eventsWithEventBetTypes,
        this.selectedBets
      );
      this.cdRef.markForCheck();
    });
  }
}
