import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  Inject,
  OnDestroy,
  PLATFORM_ID
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DestroySubject, templatingBetSlipServiceToken } from '@honoregaming/core';
import {
  BetCategoryType,
  EventBetType,
  EventType,
  InsaLeagueEnum,
  Match,
  SelectableEventBetTypeItem
} from '@honoregaming/types';
import { InstantLeagueRound } from '../../models/instant-league-round.model';
import { Match as RoundMatch } from '../../models/instant-league-match.model';
import { InstantLeagueService } from '../../services/instant-league.service';
import { finalize, take, takeUntil } from 'rxjs/operators';
import { InstantLeagueBetType } from '../../enums/instant-league-bettype.enum';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import { I18nService } from '@honoregaming/i18n';
import { Team } from '../../models/instant-league-ranking-response.model';
import { MATCH_DURATION } from '../../constants/intant-league-round.consts';
import { isPlatformBrowser } from '@angular/common';

@Component({
  selector: 'hg-instant-league-matches',
  templateUrl: './instant-league-matches.component.html',
  styleUrls: ['./instant-league-matches.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantLeagueMatchesComponent extends DestroySubject implements OnInit, OnDestroy {
  loading = false;
  matchLoading = false;
  liveLoading = false;
  error = false;
  updateGoalsAtStart = false;
  entryPointId: number;
  lightRounds: { time: Date; id: number; roundNumber: number }[];
  rounds: InstantLeagueRound[];
  activeRound: InstantLeagueRound;
  activeRoundIsLive: boolean;
  activeBetType: EventBetType;
  betTypeList: EventBetType[];
  isActiveBetCustomDisplay: boolean = true;
  isActiveBetOverUnder: boolean = false;
  selectedItems: number[] = [];
  roundDuration: number = 65;

  constructor(
    private readonly instantLeagueService: InstantLeagueService,
    private readonly i18nService: I18nService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(PLATFORM_ID) private readonly platformId,
    @Inject(templatingBetSlipServiceToken) private readonly betSlipService: BetSlipService
  ) {
    super();
    this.route.params.subscribe(params => {
      var eventCategoryId = +params.eventCategoryId;
      if (this.entryPointId != undefined && this.entryPointId != eventCategoryId) {
        this.entryPointId = eventCategoryId;
        this.betTypeList = [];
        this.loadRounds();
      } else {
        this.entryPointId = eventCategoryId;
      }
    });
  }

  ngOnInit() {
    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(_ => {
      this.loadRounds();
      this.cdRef.markForCheck();
    });

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(event => {
      this.selectedItems = event.lines.map(e => {
        return e.eventBetTypeItemId;
      });

      this.cdRef.markForCheck();
    });

    if (isPlatformBrowser(this.platformId)) {
      window.addEventListener('focus', this.handleWindowFocus);
    }
  }

  ngOnDestroy() {
    super.ngOnDestroy();

    if (isPlatformBrowser(this.platformId)) {
      window.removeEventListener('focus', this.handleWindowFocus);
    }
  }

  handleWindowFocus = () => {
    this.loadRounds();
    this.cdRef.markForCheck();
  };

  loadRounds() {
    this.error = false;
    this.loading = true;
    this.instantLeagueService
      .getLeagueMatches(this.entryPointId)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        result => {
          if (result.rounds) {
            // FIX 18546 : Because of browser's cache, we need to create a deep copy, otherwise the result is modified at each load.
            this.rounds = JSON.parse(JSON.stringify(result.rounds));

            if (!this.rounds[0].matches.every(m => m.eventBetTypes)) {
              this.error = true;
            }
            this.lightRounds = this.rounds.map(round => {
              return { time: new Date(round.expectedStart), id: round.id, roundNumber: round.roundNumber };
            });
            this.activeRound = this.rounds[0];
            this.updateGoalsAtStart = true;
            this.activeRoundIsLive = this.updateGoalsAtStart = new Date(this.activeRound.expectedStart) < new Date();

            if (!this.betTypeList || this.betTypeList.length === 0) {
              this.betTypeList = this.getBetTypeListFromEventBetTypeList(
                this.activeRound.matches[0].eventBetTypes,
                this.activeRound.matches[0].homeTeam,
                this.activeRound.matches[0].awayTeam
              );
            }

            // For Insa League only
            if (InsaLeagueEnum[this.entryPointId]) {
              this.roundDuration = 45;
            }
            this.updateActiveBetType({ betTypeId: InstantLeagueBetType.MATCHRESULT });
          } else {
            this.error = true;
          }
        },
        _ => {
          this.error = true;
        }
      );
  }

  switchRound(roundId: number) {
    this.activeRound = this.rounds.find(x => x.id === roundId);
    this.activeRoundIsLive = new Date(this.activeRound.expectedStart) < new Date();
    if (!this.activeRound.matches) {
      this.matchLoading = true;
      this.instantLeagueService
        .getRound(this.activeRound.eventCategoryId, roundId)
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.matchLoading = false;
            this.cdRef.markForCheck();
          })
        )
        .subscribe(
          result => {
            this.activeRound.matches = result.round.matches;
            if (!this.activeRound.matches.every(m => m.eventBetTypes)) {
              this.error = true;
            }
            this.updateActiveBetType({ betTypeId: InstantLeagueBetType.MATCHRESULT }, result.round.matches);
          },
          _ => {
            this.error = true;
          }
        );
    } else {
      this.updateActiveBetType({ betTypeId: InstantLeagueBetType.MATCHRESULT });
    }
  }

  checkForGoalAt(event: { minute: number; id: number }) {
    if (event.minute < 0) {
      this.activeRoundIsLive = false;
      return;
    }

    const liveRound = this.rounds.find(x => x.id === event.id);
    this.activeRoundIsLive = liveRound.id === this.activeRound.id;

    liveRound.matches?.forEach(m => {
      var goals = m.goals?.filter(z => z.minute <= event.minute);
      if (goals && goals.length) {
        m.homeTeam.scoreAtGivenTime = goals[goals.length - 1].homeScore;
        m.awayTeam.scoreAtGivenTime = goals[goals.length - 1].awayScore;
      }
    });
  }

  fetchRoundPlayout(roundId: number, tries: number = 0) {
    this.liveLoading = true;
    var eventCategoryId = this.rounds?.find(x => x.id === roundId)?.eventCategoryId;
    if (eventCategoryId) {
      this.instantLeagueService
        .getRoundPlayout(this.entryPointId, eventCategoryId, roundId)
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.cdRef.markForCheck();
          })
        )
        .subscribe(
          result => {
            if (result && result.matches.some(m => m.goals?.length > 0)) {
              this.liveLoading = false;
              if (this.rounds[0].matches?.length) {
                this.rounds[0].matches.forEach(m => {
                  const match = result.matches.find(r => r.id === m.id);
                  m.goals = match?.goals || [];
                  return m;
                });
              }
            } else if (tries < MATCH_DURATION) {
              setTimeout(() => {
                this.fetchRoundPlayout(roundId, tries + 1);
              }, 1000);
            } else {
              this.liveLoading = false;
            }
          },
          _ => {
            if (tries < MATCH_DURATION) {
              setTimeout(() => {
                this.fetchRoundPlayout(roundId, tries + 1);
              }, 1000);
            } else {
              this.liveLoading = false;
            }
          }
        );
    }
  }

  loadNextRound() {
    this.rounds.shift();
    this.lightRounds.shift();

    this.instantLeagueService
      .getRound(this.rounds[this.rounds.length - 1].eventCategoryId, this.rounds[this.rounds.length - 1].id, true)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(newRound => {
        this.rounds.push(newRound.round);
        this.lightRounds.push({
          time: new Date(newRound.round.expectedStart),
          id: newRound.round.id,
          roundNumber: newRound.round.roundNumber
        });
      });
  }

  updateActiveBetType(betType: { betTypeId: number; betTypeContext?: string }, matches: RoundMatch[] = []) {
    this.activeRound = this.rounds.find(x => x.id === this.activeRound.id);
    if (this.activeRound.matches) {
      this.activeRound.matches = this.activeRound.matches.map(x => {
        return { ...x, selectedEventBetTypeList: x.eventBetTypes.filter(y => y.betTypeId === betType.betTypeId) };
      });
    } else if (matches?.length) {
      this.activeRound.matches = matches.map(x => {
        return { ...x, selectedEventBetTypeList: x.eventBetTypes.filter(y => y.betTypeId === betType.betTypeId) };
      });
    }
    this.activeBetType = this.betTypeList.find(
      x => x.betTypeId === betType.betTypeId && x.betTypeContext === betType.betTypeContext
    );
    this.isActiveBetCustomDisplay = Object.values(InstantLeagueBetType).includes(betType.betTypeId);
    this.isActiveBetOverUnder = betType.betTypeId === 30087;
    this.cdRef.markForCheck();
  }

  getBetTypeListFromEventBetTypeList(eventBetTypeList: EventBetType[], homeTeam: Team, awayTeam: Team) {
    const result: EventBetType[] = [];
    eventBetTypeList.forEach(x => {
      if (x.betTypeId === 30095 || x.betTypeId === 30096 || x.betTypeId === 30097 || x.betTypeId === 30098) {
        x.name = x.name.replace(homeTeam.name, this.i18nService.translateSync('HOME_TEAM'));
        x.name = x.name.replace(awayTeam.name, this.i18nService.translateSync('AWAY_TEAM'));
      }

      if (x.betTypeContext && JSON.parse(x.betTypeContext).total) {
        x.name = `${x.name} ${JSON.parse(x.betTypeContext).total}`;
      }
      result.push(x);
    });
    return result;
  }

  toggleBet(eventBetTypeItem: SelectableEventBetTypeItem, event: Event, match: RoundMatch, ebt: EventBetType) {
    event.preventDefault();
    event.stopImmediatePropagation();

    if (
      !eventBetTypeItem.odds ||
      eventBetTypeItem.odds <= 1 ||
      !eventBetTypeItem.active ||
      !eventBetTypeItem.bettingAllowed
    ) {
      return;
    }

    const newMatch = {
      id: match.id,
      eventType: EventType.Match,
      homeTeamName: match['homeTeam'].name,
      awayTeamName: match['awayTeam'].name,
      name: match.name,
      entryPointId: match.entryPointId
    } as Match;

    const isSelected: boolean = !this.selectedItems.includes(eventBetTypeItem.id);
    this.selectedItems.push(eventBetTypeItem.id);
    this.cdRef.markForCheck();

    this.betSlipBetLinesService
      .toggleEventBetTypeItem(newMatch, ebt, eventBetTypeItem, isSelected, BetCategoryType.VirtualFixedOdds)
      .pipe(take(1))
      .subscribe((selected: boolean) => {
        if (isSelected && !selected) {
          this.selectedItems = this.selectedItems.filter(
            (selectedItem: number) => selectedItem !== eventBetTypeItem.id
          );
          this.cdRef.markForCheck();
        }
      });
  }

  goToMatch(match: RoundMatch) {
    this.router.navigateByUrl('/virtual/category/' + match.entryPointId + '/match/' + match.id);
  }
}
