import { Component, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { EventBetTypeItem } from '@honoregaming/types';
import { DestroySubject, BroadcastingService, ApplicationEvent } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';
import { ActivatedRoute } from '@angular/router';

@Component({
  selector: 'hg-numbers-game',
  templateUrl: './numbers-game.component.html',
  styleUrls: ['./numbers-game.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NumbersGameComponent extends DestroySubject implements OnInit {
  public eventId: number;

  private selectionChoosen = new Array<EventBetTypeItem>();

  constructor(private broadcastingService: BroadcastingService, private route: ActivatedRoute) {
    super();
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      this.eventId = +params['eventId'];
    });
    this.selectionChoosen = new Array<EventBetTypeItem>(0);

    this.broadcastingService
      .register<EventBetTypeItem>(ApplicationEvent.SelectionItemAdded)
      .pipe(takeUntil(this.destroy$))
      .subscribe(item => {
        this.selectionChoosen.push(item);
      });

    this.broadcastingService
      .register<EventBetTypeItem>(ApplicationEvent.SelectionItemRemoved)
      .pipe(takeUntil(this.destroy$))
      .subscribe(item => {
        const foundItem = this.selectionChoosen.find(i => i.id === item.id);
        if (foundItem) {
          const itemIndex = this.selectionChoosen.indexOf(foundItem);
          if (itemIndex > -1) {
            this.selectionChoosen.splice(itemIndex, 1);
          }
        }
      });

    this.broadcastingService
      .register(ApplicationEvent.SelectionReset)
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        this.selectionChoosen = new Array<EventBetTypeItem>(0);
      });
  }
}
