import { Directive, OnChanges, Input, SimpleChanges, ElementRef } from '@angular/core';

@Directive({
  selector: '[hgBlinkHighlight]'
})
export class BlinkHighlightDirective implements OnChanges {
  @Input() public hgBlinkHighlight: any;

  constructor(private elementRef: ElementRef) {}

  ngOnChanges(changes: SimpleChanges) {
    if (
      changes.hgBlinkHighlight &&
      changes.hgBlinkHighlight.previousValue !== undefined &&
      changes.hgBlinkHighlight.currentValue !== changes.hgBlinkHighlight.previousValue
    ) {
      (this.elementRef.nativeElement as HTMLElement).classList.add('blinking');
      setTimeout(() => {
        (this.elementRef.nativeElement as HTMLElement).classList.remove('blinking');
      }, 1500);
    }
  }
}
