import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter } from '@angular/core';
import { LuckyLootItemColor, SelectableEventBetTypeItem } from '@honoregaming/types';
@Component({
  selector: 'hg-lucky-loot-colors-or-more',
  templateUrl: './lucky-loot-colors-or-more.component.html',
  styleUrls: ['./lucky-loot-colors-or-more.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LuckyLootColorsOrMoreComponent {
  @Input()
  eventBetTypeItems: SelectableEventBetTypeItem[];

  @Input()
  isFirstColorBetType = false;

  @Output()
  selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  LuckyLootItemColor = LuckyLootItemColor;

  firstColorsOrMoreBetType: { [id: string]: number } = {
    Green: 3362,
    Yellow: 3363,
    Blue: 3364,
    Red: 3365
  };

  colorsOrMoreBetTypes: { [id: string]: number } = {
    Green: 3366,
    Yellow: 3367,
    Blue: 3368,
    Red: 3369
  };

  addToBetSlip(color: LuckyLootItemColor) {
    var eventBetTypeItem: SelectableEventBetTypeItem;
    eventBetTypeItem = this.eventBetTypeItems.find(
      ebti =>
        ebti.betTypeItemId ===
        (this.isFirstColorBetType ? this.firstColorsOrMoreBetType[color] : this.colorsOrMoreBetTypes[color])
    );
    this.selectionChanged.emit(eventBetTypeItem);
  }
}
