import { Component, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Event } from '@honoregaming/types';

@Component({
  selector: 'hg-virtual-event-bet-types',
  templateUrl: './virtual-event-bet-types.component.html',
  styleUrls: ['./virtual-event-bet-types.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class VirtualEventBetTypesComponent implements OnInit {
  public eventId: number;
  public eventCategoryId: number;

  constructor(private route: ActivatedRoute, private router: Router) {}

  ngOnInit() {
    this.route.params.subscribe(params => {
      if (this.eventId !== +params['eventId']) {
        this.eventCategoryId = +params['eventCategoryId'];
        this.eventId = +params['eventId'];
      }
    });
  }

  public onGoBack(evt: { event: Event; isExpired: boolean }) {
    if (evt.event && !evt.isExpired) {
      this.router.navigateByUrl('/virtual/category/' + evt.event.entryPointId);
    } else {
      this.router.navigate(['/virtual']);
    }
  }
}
