import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { EventBetType } from '@honoregaming/types';
import { INavigationService } from '@honoregaming/core';
import { Subject } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class VirtualNavigationService implements INavigationService {
  constructor(private router: Router) {}

  private goBackSubject = new Subject<{}>();
  public goBack$ = this.goBackSubject.asObservable();

  goToItemsOrRunners(eventCategoryId: number, eventId: number, eventBetType: EventBetType): void {
    if (eventBetType) {
      if (eventBetType.eventBetTypeItems && eventBetType.eventBetTypeItems.length > 0) {
        //spin and win eventCategoryId = 8025
        if (eventCategoryId === 8025) {
          this.router.navigateByUrl(
            '/virtual/category/' + eventCategoryId + '/numbers-game/' + eventId + '/' + eventBetType.id + '/items'
          );
        } else {
          this.router.navigateByUrl(
            '/virtual/category/' + eventCategoryId + '/race/' + eventId + '/' + eventBetType.id + '/items'
          );
        }
      } else {
        this.router.navigateByUrl(
          '/virtual/category/' + eventCategoryId + '/race/' + eventId + '/' + eventBetType.id + '/runners'
        );
      }
    }
  }

  public goBack(): void {
    this.goBackSubject.next();
  }
}
