import { Component, OnInit, ChangeDetectionStrategy, PLATFORM_ID, Inject } from '@angular/core';
import { Observable, Subject, Subscription } from 'rxjs';
import { IContainer } from '@honoregaming/customer-core';
import { BetSlipService } from '@honoregaming/betslip';
import { BetCategoryType } from '@honoregaming/types';
import { Router } from '@angular/router';
import { isPlatformServer } from '@angular/common';
import { DestroySubject, Scope, scopeToken } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-virtual-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LayoutComponent extends DestroySubject implements OnInit, IContainer {
  subscriptionSubject = new Subject<{ eventSubscriptions: number[]; betTypeSubscriptions: number[] }>();
  isServer = isPlatformServer(this.platformId);
  Scope = Scope;
  displayBanner: boolean = false;

  eventCategoryId: number;

  constructor(
    private router: Router,
    private betSlipService: BetSlipService,
    @Inject(PLATFORM_ID) private platformId,
    @Inject(scopeToken) public scope: Scope
  ) {
    super();
  }

  ngOnInit() {
    this.betSlipService.changeCurrentBetCategory(BetCategoryType.VirtualFixedOdds);
    this.updateDisplayBanner();
    this.router.events.pipe(takeUntil(this.destroy$)).subscribe(_ => {
      this.updateDisplayBanner();
    });
  }

  getSubscription(): Observable<{ eventSubscriptions: number[]; betTypeSubscriptions: number[] }> {
    return this.subscriptionSubject;
  }

  // tslint:disable-next-line: member-ordering
  pushSubscription: Subscription;
  onActivate(component: IContainer) {
    if (this.pushSubscription && !this.pushSubscription.closed) {
      this.pushSubscription.unsubscribe();
    }
    if (component.getSubscription) {
      this.pushSubscription = component.getSubscription().subscribe(subs => {
        this.subscriptionSubject.next(subs);
      });
    }
  }

  entryPointIndex(eventCategoryId: number) {
    this.eventCategoryId = eventCategoryId;
  }

  navigated(eventCategoryId: number) {
    this.router.navigate(['/virtual/category', eventCategoryId]);
  }

  private updateDisplayBanner(): void {
    const relativeUrl: string = this.router.url.split('?')[0];
    this.displayBanner = relativeUrl === '/virtual';
  }
}
