import { Component, ChangeDetectionStrategy, OnInit, Input, EventEmitter, Output, OnChanges } from '@angular/core';
import { SelectableEventBetTypeItem } from '@honoregaming/types';
import { RouletteItemSize } from '@honoregaming/ui';

@Component({
  selector: 'hg-spin-and-win-corner',
  templateUrl: './spin-and-win-corner.component.html',
  styleUrls: ['./spin-and-win-corner.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinCornerComponent implements OnInit, OnChanges {
  @Input()
  eventBetTypeItems: SelectableEventBetTypeItem[];
  orderedEventBetTypeItems: SelectableEventBetTypeItem[] = [];

  @Output()
  selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  RouletteItemSize = RouletteItemSize;
  items: { id: number; selected: boolean }[][] = [[], [], [], [], [], [], [], [], [], [], [], []];

  constructor() {}

  ngOnInit() {
    // Creates the 3x12 roulette items table to display
    let line = 0;
    for (let i = 1; i <= 36; i++) {
      this.items[line].push({ id: i, selected: false });
      if (i % 3 === 0) {
        line++;
      }
    }
    this.updateSelectedItems();
  }

  ngOnChanges() {
    this.orderedEventBetTypeItems = [];
    for (let id = 3277; id <= 3299; id++) {
      this.orderedEventBetTypeItems.push(this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === id));
    }
  }

  addOrRemoveItemToSelection(eventBetTypeItem: SelectableEventBetTypeItem) {
    this.selectionChanged.emit(eventBetTypeItem);
    this.updateSelectedItems();
  }

  updateSelectedItems() {
    const selectedRouletteItems = [];
    this.orderedEventBetTypeItems.forEach(ebti => {
      if (ebti.selected && this.orderedEventBetTypeItems.indexOf(ebti) > 0) {
        this.spinAndWinCorner[this.orderedEventBetTypeItems.indexOf(ebti) - 1].forEach(i => {
          selectedRouletteItems.push(i);
        });
      }
    });

    for (let line = 0; line < 12; line++) {
      for (let column = 0; column < 3; column++) {
        if (selectedRouletteItems.indexOf(this.items[line][column].id) > -1) {
          this.items[line][column].selected = true;
        } else {
          this.items[line][column].selected = false;
        }
      }
    }
  }

  // tslint:disable-next-line: member-ordering
  spinAndWinCorner: { [id: number]: number[] } = {
    0: [1, 2, 4, 5],
    1: [2, 3, 5, 6],
    2: [4, 5, 7, 8],
    3: [5, 6, 8, 9],
    4: [7, 8, 10, 11],
    5: [8, 9, 11, 12],
    6: [10, 11, 13, 14],
    7: [11, 12, 14, 15],
    8: [13, 14, 16, 17],
    9: [14, 15, 17, 18],
    10: [16, 17, 19, 20],
    11: [17, 18, 20, 21],
    12: [19, 20, 22, 23],
    13: [20, 21, 23, 24],
    14: [22, 23, 25, 26],
    15: [23, 24, 26, 27],
    16: [25, 26, 28, 29],
    17: [26, 27, 29, 30],
    18: [28, 29, 31, 32],
    19: [29, 30, 33, 33],
    20: [31, 32, 34, 35],
    21: [32, 33, 35, 36]
  };
}
