import {
  ChangeDetectionStrategy,
  Component,
  ChangeDetectorRef,
  OnInit,
  Inject,
  PLATFORM_ID,
  OnDestroy
} from '@angular/core';
import { getUtcNow, delayBetween, EntryPoints, ApplicationStateService } from '@honoregaming/core';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import {
  SelectableEventBetTypeItem,
  EventWithEventBetType,
  EventType,
  BetCategoryType,
  Event,
  EventWithEventBetTypes,
  SelectedItem
} from '@honoregaming/types';
import { EventsService, FetchEventBetTypesMode, EventsMapperService } from '@honoregaming/events';
import { ActivatedRoute } from '@angular/router';
import { EventWithEventBetTypeBaseComponent } from '../../event-with-eventbettype.basecomponent';
import { trigger, transition, animate, style } from '@angular/animations';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '@honoregaming/customer-core';
import { isPlatformBrowser } from '@angular/common';
import { EventWithEventBetTypeIsAboutToStart } from '../../models/event-about-to-start.model';
import { registerForEventIsAboutToStartNotification } from '../../helpers/event.helpers';
import { skip, takeUntil, take } from 'rxjs/operators';
import { merge } from 'rxjs';

@Component({
  selector: 'hg-eventcategory-with-events',
  templateUrl: './eventcategory-with-events.component.html',
  styleUrls: ['./eventcategory-with-events.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    trigger('removed', [
      transition('* => void', [animate('0.1s ease-out', style({ transform: 'scale(0)', height: '0' }))])
    ])
  ]
})
export class EventCategoryWithEventsComponent extends EventWithEventBetTypeBaseComponent implements OnInit, OnDestroy {
  eventCategoryId: number;
  loading = false;
  loadingMore = false;
  EventType = EventType;
  EntryPoint = EntryPoints;

  page: number;
  hasMore: boolean;

  eventsWithEventBetTypes: EventWithEventBetTypeIsAboutToStart<Event>[] = [];
  selectedBets: { eventId: number; betTypeId: number; eventBetTypeItemId: number }[];

  private oldEventsCleanTimer: any;

  constructor(
    protected readonly eventsMapperService: EventsMapperService,
    protected readonly betSlipService: BetSlipService,
    protected readonly cdRef: ChangeDetectorRef,
    private readonly route: ActivatedRoute,
    private readonly eventsService: EventsService,
    private readonly appStateService: ApplicationStateService,
    private readonly betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(PLATFORM_ID) private readonly platformId
  ) {
    super(betSlipService, eventsMapperService, cdRef);
  }

  ngOnInit() {
    super.ngOnInit();

    this.route.params.subscribe(params => {
      if (this.eventCategoryId !== +params['eventCategoryId']) {
        this.loading = true;
        this.cdRef.markForCheck();

        this.page = 0;
        this.eventCategoryId = +params['eventCategoryId'];

        this.eventsWithEventBetTypes = new Array<EventWithEventBetType<Event>>();

        this.eventsService
          .getEvents([this.eventCategoryId], 0, 20, FetchEventBetTypesMode.Default)
          .pipe(takeUntil(merge(this.route.params.pipe(skip(1)), this.destroy$)))
          .subscribe(events => {
            this.hasMore = events.hasMore;

            this.fillEvents(events.result);

            this.eventsMapperService.updateEventsWithEventBetTypesSelectedItems(
              this.eventsWithEventBetTypes,
              this.selectedBets
            );
            this.loading = false;
            this.cdRef.markForCheck();
          });
      }
    });
  }

  // tslint:disable-next-line: use-life-cycle-interface
  ngOnDestroy(): void {
    super.ngOnDestroy();

    if (this.oldEventsCleanTimer) {
      clearTimeout(this.oldEventsCleanTimer);
    }
  }

  fillEvents(eventsWithEventBetTypes: EventWithEventBetTypes<Event>[]): void {
    const filteredEvents = eventsWithEventBetTypes
      .filter(e => getUtcNow() < new Date(e.expectedStart) && e.eventBetTypes && e.eventBetTypes.length > 0)
      .sort((a, b) =>
        new Date(a.expectedStart) > new Date(b.expectedStart)
          ? 1
          : new Date(a.expectedStart) < new Date(b.expectedStart)
          ? -1
          : 0
      );

    filteredEvents.forEach(e => {
      if (this.eventsWithEventBetTypes.findIndex(evt => evt.id === e.id) === -1) {
        this.eventsWithEventBetTypes.push({
          ...e,
          eventBetType: e.eventBetTypes[0]
        });
      }
    });

    if (this.eventsWithEventBetTypes && this.eventsWithEventBetTypes.length && isPlatformBrowser(this.platformId)) {
      this.appStateService.isReady$.pipe(take(1)).subscribe(() => {
        this.checkIfEventsAreAboutToStart();
        this.removeOldEvents();
      });
    }
  }

  private checkIfEventsAreAboutToStart(): void {
    const nextEventsAboutToStart = this.eventsWithEventBetTypes.filter(e => !e.isAboutToStart);
    if (nextEventsAboutToStart && nextEventsAboutToStart.length) {
      registerForEventIsAboutToStartNotification(
        nextEventsAboutToStart[0].expectedStart,
        this.operatorConfiguration.virtualConfiguration.delayBeforeVirtualEventIsGoingLive
      ).subscribe(_ => {
        const areAboutToStartEvents = this.eventsWithEventBetTypes.filter(
          ebt =>
            ebt.expectedStart.getTime() -
              this.operatorConfiguration.virtualConfiguration.delayBeforeVirtualEventIsGoingLive * 60000 <=
            getUtcNow().getTime()
        );
        if (areAboutToStartEvents.length) {
          areAboutToStartEvents.forEach(evt => {
            const index = this.eventsWithEventBetTypes.indexOf(evt, 0);
            if (index > -1) {
              this.eventsWithEventBetTypes[index] = { ...evt, isAboutToStart: true };
            }
          });

          this.cdRef.markForCheck();
          this.checkIfEventsAreAboutToStart();
        }
      });
    }
  }

  private removeOldEvents(): void {
    this.oldEventsCleanTimer = setTimeout(() => {
      if (this.oldEventsCleanTimer) {
        clearTimeout(this.oldEventsCleanTimer);
      }

      const expiredEvents = this.eventsWithEventBetTypes.filter(ebt => new Date(ebt.expectedStart) <= getUtcNow());
      if (expiredEvents.length) {
        expiredEvents.forEach(evt => {
          const index = this.eventsWithEventBetTypes.indexOf(evt, 0);
          if (index > -1) {
            this.eventsWithEventBetTypes.splice(index, 1);
          }
        });

        this.cdRef.markForCheck();
        this.eventsService
          .getEvents([this.eventCategoryId], 0, 20, FetchEventBetTypesMode.All)
          .pipe(takeUntil(this.destroy$))
          .subscribe(results => {
            this.hasMore = results.hasMore;

            this.fillEvents(results.result);

            this.cdRef.markForCheck();
          });
      }
    }, delayBetween(getUtcNow(), new Date(this.eventsWithEventBetTypes[0].expectedStart)));
  }

  onBetSelectionChanged(
    event: EventWithEventBetType<Event>,
    selection: {
      item: SelectableEventBetTypeItem;
      selected: boolean;
    }
  ) {
    if (!this.selectedBets) {
      this.selectedBets = [];
    }
    this.selectedBets.push({
      eventId: event.id,
      betTypeId: event.eventBetType.id,
      eventBetTypeItemId: selection.item.id
    });

    this.betSlipBetLinesService
      .toggleEventBetTypeItem(
        event,
        event.eventBetType,
        selection.item,
        selection.selected,
        BetCategoryType.VirtualFixedOdds
      )
      .pipe(take(1))
      .subscribe((selected: boolean) => {
        if (selection.selected && !selected) {
          this.selectedBets = this.selectedBets.filter(
            (selectedItem: SelectedItem) => selectedItem.eventBetTypeItemId !== selection.item.id
          );
          this.eventsMapperService.updateEventsWithEventBetTypesSelectedItems(
            this.eventsWithEventBetTypes,
            this.selectedBets
          );
          this.cdRef.markForCheck();
        }
      });
  }

  trackEvent(_index: number, eventBetType: EventWithEventBetTypes<Event>) {
    return eventBetType.id;
  }

  public loadMoreEvents(): void {
    this.loadingMore = true;

    this.eventsService
      .getEvents([this.eventCategoryId], ++this.page, 20, FetchEventBetTypesMode.All)
      .pipe(takeUntil(merge(this.route.params.pipe(skip(1)), this.destroy$)))
      .subscribe(events => {
        this.hasMore = events.hasMore;

        events.result.forEach(e => {
          this.eventsWithEventBetTypes.push({
            ...e,
            eventBetType: e.eventBetTypes[0]
          });
        });

        this.loadingMore = false;
        this.cdRef.markForCheck();
      });
  }
}
