import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, PLATFORM_ID } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Race, EventStateType } from '@honoregaming/types';
import { EventsService } from '@honoregaming/events';
import { navigationServiceToken, INavigationService, DestroySubject } from '@honoregaming/core';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '@honoregaming/customer-core';
import {
  eventIsAboutToStart,
  registerForEventIsAboutToStartNotification,
  registerForEventStartsNotification
} from '../../helpers/event.helpers';
import { skip, takeUntil } from 'rxjs/operators';
import { isPlatformBrowser } from '@angular/common';
import { EventWithEventBetTypesIsAboutToStart } from '../../models/event-about-to-start.model';
import { merge } from 'rxjs';

@Component({
  selector: 'hg-race-layout',
  templateUrl: './race-layout.component.html',
  styleUrls: ['./race-layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RaceLayoutComponent extends DestroySubject implements OnInit {
  raceId: number;

  EventStateType = EventStateType;
  race: EventWithEventBetTypesIsAboutToStart<Race>;
  loading = false;

  public isAboutToStart: boolean;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private cdRef: ChangeDetectorRef,
    private eventsService: EventsService,
    @Inject(navigationServiceToken) private navigationService: INavigationService,
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(PLATFORM_ID) private platformId
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;

    this.route.params.subscribe(params => {
      if (this.raceId !== +params['eventId']) {
        this.raceId = +params['eventId'];
        this.race = this.eventsService.getEventFromCache(this.raceId);
        if (this.race) {
          if (isPlatformBrowser(this.platformId)) {
            this.registerEventLifeCycle();
          }

          this.loading = false;
          this.cdRef.markForCheck();
        } else {
          this.eventsService
            .getEventDetails(this.raceId)
            .pipe(takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)))))
            .subscribe(
              e => {
                this.race = e as Race;

                if (isPlatformBrowser(this.platformId)) {
                  this.registerEventLifeCycle();
                }

                this.loading = false;
                this.cdRef.markForCheck();
              },
              e => {
                if (e.status === 404) {
                  this.router.navigate(['/virtual']);
                }
              }
            );
        }
      }
    });
  }

  private registerEventLifeCycle(): void {
    this.isAboutToStart = eventIsAboutToStart(
      this.race.expectedStart,
      this.operatorConfiguration.virtualConfiguration.delayBeforeVirtualEventIsGoingLive
    );

    if (!this.isAboutToStart) {
      registerForEventIsAboutToStartNotification(
        this.race.expectedStart,
        this.operatorConfiguration.virtualConfiguration.delayBeforeVirtualEventIsGoingLive
      )
        .pipe(takeUntil(this.destroy$))
        .subscribe(_ => {
          this.isAboutToStart = true;
          this.cdRef.markForCheck();
        });
    }

    registerForEventStartsNotification(this.race.expectedStart)
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        this.isAboutToStart = false;
        this.cdRef.markForCheck();
      });
  }

  public goBack(): void {
    this.navigationService.goBack();
  }
}
