import { isPlatformBrowser } from '@angular/common';
import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  Inject,
  Input,
  Output,
  EventEmitter,
  PLATFORM_ID,
  NgZone,
  OnDestroy,
  HostBinding
} from '@angular/core';
import { Subscription } from 'rxjs';
import { finalize, take, takeUntil } from 'rxjs/operators';
import { EventsService } from '@honoregaming/events';
import { EventBetType, SelectableEventBetTypeItem, BetCategoryType, Event, EventType, Race } from '@honoregaming/types';
import { BetSlipService, BetSlipBetLinesService } from '@honoregaming/betslip';
import {
  getUtcNow,
  DestroySubject,
  navigationServiceToken,
  INavigationService,
  delayBetween,
  ApplicationStateService,
  OddsPreviewerVisibilityService,
  EntryPoints
} from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { OddsPreviewerState } from '@honoregaming/ui';
import { VirtualRaceService } from '../../services';

@Component({
  selector: 'hg-event-bet-type-items',
  templateUrl: './event-bet-type-items.component.html',
  styleUrls: ['./event-bet-type-items.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventBetTypeItemsComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input() eventId!: number;
  @Input() eventBetTypeId!: number;

  @Output() goBack = new EventEmitter<{ event: Event; isExpired: boolean }>();

  event?: Event;
  eventBetType?: EventBetType;
  internalEventBetTypeItems: SelectableEventBetTypeItem[] = [];

  isLoading: boolean = false;
  isEventExpired: boolean = false;
  error: boolean = false;

  private betLinesSubscription?: Subscription;
  private oldEventCleanTimer?: NodeJS.Timeout;

  EventType = EventType;

  constructor(
    private readonly eventsService: EventsService,
    private readonly i18nService: I18nService,
    private readonly betSlipService: BetSlipService,
    private readonly zone: NgZone,
    private readonly oddsPreviewerVisibilityService: OddsPreviewerVisibilityService,
    private readonly applicationStateService: ApplicationStateService,
    private readonly virtualRaceService: VirtualRaceService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(navigationServiceToken) private readonly navigationService: INavigationService,
    @Inject(PLATFORM_ID) private readonly platformId: Object
  ) {
    super();
  }

  public ngOnInit(): void {
    this.isLoading = true;

    this.eventsService
      .getEventDetails(this.eventId)
      .pipe(
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        e => {
          if (getUtcNow() >= new Date(e.expectedStart)) {
            this.isEventExpired = true;
          } else {
            this.event = e;
            this.eventBetType = e.eventBetTypes?.find(ebt => ebt.id === this.eventBetTypeId);
            this.internalEventBetTypeItems = this.eventBetType?.eventBetTypeItems;

            const race: Race = this.event;

            if (race.runners && this.internalEventBetTypeItems) {
              for (let i = 0; i < this.internalEventBetTypeItems.length; i++) {
                this.internalEventBetTypeItems[i].runnerName = race.runners.find(
                  runner => runner.number.toString() == this.internalEventBetTypeItems[i].shortName
                )?.name;
              }
            }

            if (isPlatformBrowser(this.platformId)) {
              this.applicationStateService.isReady$.subscribe(() => {
                this.disableEventWhenExpired();
              });
            }

            this.subscribeToBetLinesChanges();
          }
        },
        _ => {
          this.error = true;
        }
      );

    this.navigationService.goBack$.pipe(takeUntil(this.destroy$)).subscribe(_ => {
      if (this.goBack) {
        this.goBack.emit({ event: this.event, isExpired: this.isEventExpired });
      }
    });
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();

    if (this.oldEventCleanTimer) {
      clearTimeout(this.oldEventCleanTimer);
    }
  }

  @HostBinding('class.is-lucky-loot')
  get isLuckyLoot() {
    return this.event?.eventType === EventType.NumbersGame && this.event.entryPointId === EntryPoints.LuckyLoot;
  }

  private disableEventWhenExpired(): void {
    this.oldEventCleanTimer = setTimeout(() => {
      if (this.oldEventCleanTimer) {
        clearTimeout(this.oldEventCleanTimer);
      }

      this.isEventExpired = true;
      this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(OddsPreviewerState.Closed);
      this.zone.run(() => this.cdRef.markForCheck());
    }, delayBetween(getUtcNow(), new Date(this.event.expectedStart)));
  }

  subscribeToBetLinesChanges(): void {
    if (!this.betLinesSubscription) {
      this.betLinesSubscription = this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(event => {
        for (let i = 0; i < this.internalEventBetTypeItems?.length; i++) {
          if (!!this.internalEventBetTypeItems[i].selected) {
            this.internalEventBetTypeItems[i].selected = false;
          }
        }

        event.lines.forEach(l => {
          if (this.eventId === l.eventId && l.eventBetTypeId === this.eventBetTypeId && !!l.eventBetTypeItemId) {
            for (let i = 0; i < this.internalEventBetTypeItems.length; i++) {
              if (this.internalEventBetTypeItems[i].id === l.eventBetTypeItemId) {
                this.internalEventBetTypeItems[i].selected = true;
              }
            }
          }
        });

        if (this.internalEventBetTypeItems) {
          this.internalEventBetTypeItems = [...this.internalEventBetTypeItems];
        }
        this.cdRef.markForCheck();
      });
    }
  }

  onSelectionChanged(item: SelectableEventBetTypeItem, isToggle: boolean = true): void {
    this.betSlipBetLinesService
      .toggleEventBetTypeItem(
        this.event,
        this.eventBetType,
        item,
        !isToggle || !item.selected,
        BetCategoryType.VirtualFixedOdds,
        this.event.eventType === EventType.NumbersGame
          ? this.i18nService.translateSync('VIRTUAL_GAMES.' + this.event.entryPointId)
          : null
      )
      .pipe(take(1))
      .subscribe((selected: boolean) => {
        if (!isToggle || (item.selected && !selected)) {
          this.internalEventBetTypeItems = this.internalEventBetTypeItems.map(
            (selectedItem: SelectableEventBetTypeItem) =>
              selectedItem.id !== item.id ? selectedItem : { ...selectedItem, selected: false }
          );
        }
        this.virtualRaceService.resetSelectedItems();
        this.cdRef.markForCheck();
      });
  }
}
