import { Injectable } from '@angular/core';
import { Observable, Subject } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class VirtualRaceService {
  private resetSelectedItemsSubject = new Subject<{}>();
  public resetSelectedItems$ = this.resetSelectedItemsSubject.asObservable();
  private displayNextVirtualSubject: Subject<string> = new Subject();
  public displayNextVirtual: Observable<string> = this.displayNextVirtualSubject.asObservable();

  constructor() {}

  public resetSelectedItems(): void {
    this.resetSelectedItemsSubject.next();
  }

  clickNextVirtual(currentId: string) {
    this.displayNextVirtualSubject.next(currentId);
  }
}
