import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, PLATFORM_ID } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import {
  EventBetTypeItem,
  EventBetType,
  SelectableEventBetTypeItem,
  EventStateType,
  BetTypeGroup,
  BetCategoryType,
  Match,
  isInsaLeaguesEntryPoint,
  SelectedItem
} from '@honoregaming/types';
import { EventsService, EventCategoriesService } from '@honoregaming/events';
import { BetSlipBetLinesService, BetSlipService } from '@honoregaming/betslip';
import { DestroySubject, getUtcNow } from '@honoregaming/core';
import { skip, take, takeUntil } from 'rxjs/operators';
import {
  eventIsAboutToStart,
  registerForEventStartsNotification,
  registerForEventIsAboutToStartNotification
} from '../../helpers/event.helpers';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '@honoregaming/customer-core';
import { isPlatformBrowser } from '@angular/common';
import { EventWithEventBetTypesIsAboutToStart } from '../../models/event-about-to-start.model';
import { merge } from 'rxjs';

@Component({
  selector: 'hg-match-with-event-bet-types',
  templateUrl: './match-with-event-bet-types.component.html',
  styleUrls: ['./match-with-event-bet-types.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class MatchWithEventBetTypesComponent extends DestroySubject implements OnInit {
  matchId: number;
  selectedBets: { eventId: number; betTypeId: number; eventBetTypeItemId: number }[];

  eventBetTypesGroupedByBetType: EventBetTypeGroupedByBetType[] = [];

  EventStateType = EventStateType;

  match: EventWithEventBetTypesIsAboutToStart<Match>;
  loading = false;
  isEventExpired: boolean;
  isAboutToStart: boolean;

  videoPlayerShouldBeOpenedByDefault: boolean =
    this.operatorConfiguration.onlineConfiguration?.openVirtualStreamingPlayerOnMobile ?? false;

  constructor(
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly betSlipService: BetSlipService,
    private readonly eventsService: EventsService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly eventCategoryService: EventCategoriesService,
    private readonly betSlipBetLinesService: BetSlipBetLinesService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(PLATFORM_ID) private readonly platformId
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;

    this.route.params.subscribe(params => {
      if (this.matchId !== +params['match']) {
        this.matchId = +params['match'];
        this.match = this.eventsService.getEventFromCache(this.matchId);
        this.eventsService
          .getEventDetails<Match>(this.matchId)
          .pipe(takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)))))
          .subscribe(
            e => {
              this.match = e;

              this.eventCategoryService
                .getEntryPoints()
                .pipe(takeUntil(merge(this.destroy$, this.route.params.pipe(skip(1)))))
                .subscribe(ep => {
                  const eventCategory = ep.find(ec => ec.id === this.match.entryPointId);
                  if (eventCategory) {
                    this.match.categories = [eventCategory.name];
                  }
                });

              this.loadData();
            },
            e => {
              if (e.status === 404) {
                this.router.navigate(['/virtual']);
              }
            }
          );
      }
    });

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(event => {
      this.selectedBets = event.lines.map(e => {
        return {
          eventId: e.eventId,
          betTypeId: e.betTypeId,
          eventBetTypeItemId: e.eventBetTypeItemId
        };
      });

      this.updateSelectedBets();
    });
  }

  private loadData() {
    if (this.match) {
      if (getUtcNow() >= new Date(this.match.expectedStart)) {
        this.isEventExpired = true;
      } else {
        if (this.match.eventBetTypes && this.match.eventBetTypes.length > 0) {
          this.eventBetTypesGroupedByBetType = this.match.eventBetTypes.reduce(
            (betTypesWithItems: EventBetTypeGroupedByBetType[], ebt) => {
              if (ebt && ebt !== null) {
                const index = betTypesWithItems.findIndex(e => e.betTypeId === ebt.betTypeId);
                const eventBetType = {
                  id: ebt.id,
                  name: ebt.name,
                  active: ebt.active,
                  bettingAllowed: ebt.bettingAllowed,
                  betTypeId: ebt.betTypeId,
                  baseAmount: ebt.baseAmount,
                  minimumAmountIncrement: ebt.minimumAmountIncrement,
                  maximumAmount: ebt.maximumAmount,
                  eventBetTypeItems: ebt.eventBetTypeItems.map(ebti => ({ ...ebti })),
                  displayPriority: ebt.displayPriority,
                  isAsian: ebt.isAsian,
                  betTypeGroup: ebt.betTypeGroup,
                  hasExplanations: ebt.hasExplanations,
                  isManual: ebt.isManual
                };
                if (index === -1) {
                  const group: EventBetTypeGroupedByBetType = {
                    betTypeId: ebt.betTypeId,
                    displayPriority: ebt.displayPriority,
                    groupName: eventBetType.name,
                    eventBetTypes: [eventBetType],
                    betTypeGroup: ebt.betTypeGroup,
                    hasExplanations: ebt.hasExplanations,
                    isManual: ebt.isManual
                  };
                  betTypesWithItems.push(group);
                } else {
                  betTypesWithItems[index].eventBetTypes.push(eventBetType);
                }
              }

              return betTypesWithItems;
            },
            []
          );

          if (isPlatformBrowser(this.platformId)) {
            this.registerEventLifeCycle();
          }
        } else {
          this.eventBetTypesGroupedByBetType = [];
        }
      }
    } else {
      this.isEventExpired = true;
    }

    this.updateSelectedBets();
    this.loading = false;
    this.cdRef.markForCheck();
  }

  private registerEventLifeCycle(): void {
    this.isAboutToStart = eventIsAboutToStart(
      this.match.expectedStart,
      this.operatorConfiguration.virtualConfiguration.delayBeforeVirtualEventIsGoingLive
    );

    if (!this.isAboutToStart) {
      registerForEventIsAboutToStartNotification(
        this.match.expectedStart,
        this.operatorConfiguration.virtualConfiguration.delayBeforeVirtualEventIsGoingLive
      )
        .pipe(takeUntil(this.destroy$))
        .subscribe(_ => {
          this.isAboutToStart = true;
          this.cdRef.markForCheck();
        });
    }

    registerForEventStartsNotification(this.match.expectedStart)
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => {
        this.isAboutToStart = false;
        this.cdRef.markForCheck();
      });
  }

  trackEventBetType(_index: number, eventBetType: EventBetTypeGroupedByBetType) {
    return eventBetType.betTypeId;
  }

  public trackEventBetTypeItem(_index: number, eventBetTypeItem: EventBetTypeItem) {
    return eventBetTypeItem.id;
  }

  toggleBet(ebt: EventBetType, item: SelectableEventBetTypeItem) {
    if (item.odds <= 1 || !ebt.active || !ebt.bettingAllowed || !item.active || !item.bettingAllowed) {
      return;
    }

    this.betSlipBetLinesService
      .toggleEventBetTypeItem(this.match, ebt, item, !item.selected, BetCategoryType.VirtualFixedOdds)
      .pipe(take(1))
      .subscribe((selected: boolean) => {
        if (item.selected && !selected) {
          this.selectedBets = this.selectedBets.filter(
            (selectedItem: SelectedItem) => selectedItem.eventBetTypeItemId !== item.id
          );
          this.updateSelectedBets();
        }
      });
  }

  updateSelectedBets() {
    if (this.eventBetTypesGroupedByBetType) {
      for (const group of this.eventBetTypesGroupedByBetType) {
        for (const eventBetType of group.eventBetTypes) {
          for (let i = 0; i < eventBetType.eventBetTypeItems.length; i++) {
            if (!!eventBetType.eventBetTypeItems[i].selected) {
              // HACK: change the ref to force the redraw
              eventBetType.eventBetTypeItems[i] = { ...eventBetType.eventBetTypeItems[i], selected: false };
            }
          }
        }
      }
    }

    if (this.selectedBets && this.eventBetTypesGroupedByBetType) {
      this.selectedBets.forEach(bet => {
        if (bet.eventId === this.matchId) {
          for (const group of this.eventBetTypesGroupedByBetType.filter(e => e.betTypeId === bet.betTypeId)) {
            for (const eventBetType of group.eventBetTypes) {
              for (let i = 0; i < eventBetType.eventBetTypeItems.length; i++) {
                if (eventBetType.eventBetTypeItems[i].id === bet.eventBetTypeItemId) {
                  // HACK: change the ref to force the redraw
                  eventBetType.eventBetTypeItems[i] = { ...eventBetType.eventBetTypeItems[i], selected: true };
                }
              }
            }
          }
        }
      });
    }

    this.cdRef.markForCheck();
  }

  goBack(): void {
    if (this.match) {
      // Instant Leagues
      if (isInsaLeaguesEntryPoint(this.match.entryPointId)) {
        this.router.navigateByUrl('/virtual/category/instant-league/' + this.match.entryPointId + '/matches');
      } else {
        this.router.navigateByUrl('/virtual/category/' + this.match.entryPointId);
      }
    } else {
      this.router.navigate(['/virtual']);
    }
  }
}

interface EventBetTypeGroupedByBetType {
  betTypeId: number;
  displayPriority: number;
  groupName: string;
  eventBetTypes: EventBetType[];
  betTypeGroup: BetTypeGroup;
  hasExplanations?: boolean;
  isManual: boolean;
}
