import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { DialogService, OddsPreviewerVisibilityService } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';
import { OddsPreviewerState } from '@honoregaming/ui';
import { AuthService, Me } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-virtual-sidebar',
  templateUrl: './sidebar.component.html',
  styleUrls: ['./sidebar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SidebarComponent extends DestroySubject implements OnInit {
  betSlipActive: boolean;
  oddsPreviewerState: OddsPreviewerState;
  me: Me;

  constructor(
    private oddsPreviewerVisibilityService: OddsPreviewerVisibilityService,
    protected authService: AuthService,
    private dialogService: DialogService,
    private cdRef: ChangeDetectorRef
  ) {
    super();
  }

  ngOnInit() {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.me = me;
      this.cdRef.markForCheck();
    });

    this.dialogService
      .registerDialog('betslip')
      .pipe(takeUntil(this.destroy$))
      .subscribe(open => {
        this.betSlipActive = open;
        this.cdRef.markForCheck();
      });

    this.oddsPreviewerVisibilityService.oddsPreviewerVisibilityChanged$
      .pipe(takeUntil(this.destroy$))
      .subscribe(isVisible => {
        this.oddsPreviewerState = isVisible;
        this.cdRef.markForCheck();
      });
  }

  openBetSlip() {
    this.dialogService.toggleDialog('betslip', !this.betSlipActive);
  }

  closeBetSlip() {
    this.dialogService.toggleDialog('betslip', false);
  }
}
