import { Component, ChangeDetectionStrategy, OnInit, Input } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { Goal } from '../../models/goal.model';
import { TeamType } from '@honoregaming/types';

@Component({
  selector: 'hg-instant-league-goal-history',
  templateUrl: './instant-league-goal-history.component.html',
  styleUrls: ['./instant-league-goal-history.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantLeagueGoalHistoryComponent extends DestroySubject implements OnInit {
  @Input() goals: Goal[] = [];
  @Input() isHomeTeam: boolean = true;

  goalHistory: string = '';

  ngOnInit(): void {
    this.goalHistory = this.goals
      .filter(g => (this.isHomeTeam ? g.team === TeamType.Home : g.team === TeamType.Away))
      .map(goal => `${goal.minute}'`)
      .join(' ')
      .trim();
  }
}
