import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, OnChanges } from '@angular/core';
import { SelectableEventBetTypeItem, EventWithEventBetTypes, Event } from '@honoregaming/types';
import { RouletteItemSize } from '@honoregaming/ui';

@Component({
  selector: 'hg-spin-and-win-color',
  templateUrl: './spin-and-win-color.component.html',
  styleUrls: ['./spin-and-win-color.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinColorComponent implements OnChanges {
  @Input()
  eventBetTypeItems: SelectableEventBetTypeItem[];
  orderedEventBetTypeItems: SelectableEventBetTypeItem[] = [];

  @Output()
  selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  RouletteItemSize = RouletteItemSize;
  event: EventWithEventBetTypes<Event>;

  spinAndWinColorBetTypes: { [id: string]: number } = {
    Green: 3201,
    Red: 3202,
    Black: 3203
  };

  ngOnChanges() {
    this.orderedEventBetTypeItems = [];
    this.orderedEventBetTypeItems.push(
      this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === this.spinAndWinColorBetTypes['Black'])
    );
    this.orderedEventBetTypeItems.push(
      this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === this.spinAndWinColorBetTypes['Red'])
    );
    this.orderedEventBetTypeItems.push(
      this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === this.spinAndWinColorBetTypes['Green'])
    );
  }

  addOrRemoveItemToSelection(eventBetTypeItem: SelectableEventBetTypeItem) {
    this.selectionChanged.emit(eventBetTypeItem);
  }
}
