import { Component, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Event } from '@honoregaming/types';

@Component({
  selector: 'hg-virtual-runners',
  templateUrl: './virtual-runners.component.html',
  styleUrls: ['./virtual-runners.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class VirtualRunnersComponent implements OnInit {
  public eventId: number;
  public eventBetTypeId: number;

  constructor(private route: ActivatedRoute, private router: Router) {}

  ngOnInit() {
    this.route.params.subscribe(params => {
      if (this.eventId !== +params['eventId'] || this.eventBetTypeId !== +params['eventBetTypeId']) {
        this.eventId = +params['eventId'];
        this.eventBetTypeId = +params['eventBetTypeId'];
      }
    });
  }

  public onGoBack(evt: { event: Event; isExpired: boolean }) {
    if (evt.event && !evt.isExpired) {
      this.router.navigateByUrl('/virtual/category/' + evt.event.entryPointId + '/race/' + evt.event.id);
    } else {
      this.router.navigate(['/virtual']);
    }
  }
}
