import { Component, ChangeDetectionStrategy, Input, EventEmitter, Output, OnInit } from '@angular/core';
import { BetCategoryType, Event, EventBetType, SelectableEventBetTypeItem } from '@honoregaming/types';
import { luckyLootItems } from '@honoregaming/ui';
import { BetLine, BetSlipService, createBetLineWithSelection } from '@honoregaming/betslip';
import { OddsPreviewerState } from '@honoregaming/ui';
import { I18nService } from '@honoregaming/i18n';
import { OddsPreviewerVisibilityService } from '@honoregaming/core';

@Component({
  selector: 'hg-lucky-loot-numbers',
  templateUrl: './lucky-loot-numbers.component.html',
  styleUrls: ['./lucky-loot-numbers.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LuckyLootNumbersComponent implements OnInit {
  @Input()
  count: number;

  @Input()
  event: Event;

  @Input()
  eventBetType: EventBetType;

  @Output()
  selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  luckyLootItems = luckyLootItems;
  selection: number[] = [];
  betLine: BetLine;
  oddsPreviewerState: OddsPreviewerState;
  stakes: number;

  constructor(
    private betSlipService: BetSlipService,
    private oddsPreviewerVisibilityService: OddsPreviewerVisibilityService,
    private i18nService: I18nService
  ) {}

  ngOnInit() {
    this.stakes = this.eventBetType.baseAmount;
  }

  toggleItem(number: number) {
    if (this.selection.indexOf(number) > -1) {
      this.selection.splice(this.selection.indexOf(number), 1);
    } else if (this.selection.length < this.count) {
      this.selection.push(number);
    }

    this.oddsPreviewerState = this.selection.length
      ? OddsPreviewerState.SelectionStakesOpened
      : OddsPreviewerState.Closed;

    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(this.oddsPreviewerState);
  }

  addToBetSlip() {
    var maxOdds = this.getMaxOdds();
    var odds = this.getOdds();

    this.betLine = createBetLineWithSelection(
      this.event,
      this.eventBetType,
      this.selection.sort((a, b) => a - b).map(s => s.toString()),
      null,
      BetCategoryType.VirtualFixedOdds,
      null,
      odds,
      null,
      null,
      maxOdds,
      this.i18nService.translateSync('VIRTUAL_GAMES.' + this.event.entryPointId)
    );

    this.betSlipService.addBetLine(this.betLine);
    this.selection = [];
    this.oddsPreviewerState = OddsPreviewerState.Closed;
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(this.oddsPreviewerState);
  }

  getMaxOdds() {
    const table = this.eventBetType.bonusPayTable || this.eventBetType.payTable;
    if (this.eventBetType.betTypeId !== 30042 && table) {
      // First x
      const keys = Object.keys(table);
      return keys.length ? table[Math.max(...keys.map(x => +x))] : null;
    }

    return null;
  }

  getOdds() {
    const table = this.eventBetType.bonusPayTable || this.eventBetType.payTable;
    if (this.eventBetType.betTypeId === 30042 && table && this.eventBetType.betTypeContext) {
      // x from 6
      const selectionLength = JSON.parse(this.eventBetType.betTypeContext).count;
      return selectionLength ? table[selectionLength] : null;
    }

    return null;
  }
}
