import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { EventStateType, EventCategory } from '@honoregaming/types';
import { DestroySubject } from '@honoregaming/core';
import { merge } from 'rxjs';
import { takeUntil, skip } from 'rxjs/operators';
import { EventCategoriesService } from '@honoregaming/events';

@Component({
  selector: 'hg-instant-league-layout',
  templateUrl: './instant-league-layout.component.html',
  styleUrls: ['./instant-league-layout.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantLeagueLayoutComponent extends DestroySubject implements OnInit {
  eventCategoryId: number;

  EventStateType = EventStateType;
  eventCategory: EventCategory;
  loading = false;

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private cdRef: ChangeDetectorRef,
    private eventCategoriesService: EventCategoriesService
  ) {
    super();
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      if (this.eventCategoryId !== +params['eventCategoryId']) {
        this.loading = true;
        this.eventCategoryId = +params['eventCategoryId'];
        this.eventCategoriesService
          .getEventCategory(this.eventCategoryId)
          .pipe(takeUntil(merge(this.route.params.pipe(skip(1)), this.destroy$)))
          .subscribe(
            e => {
              this.eventCategory = e;
              this.loading = false;
              this.cdRef.markForCheck();
            },
            e => {
              if (e.status === 404) {
                this.router.navigate(['/virtual']);
              }
            }
          );
      }
    });
  }
}
