export interface InstantLeagueRankingResponse {
  teams: Team[];
}

export interface Team {
  name: string;
  points: number;
  position: number;
  history: MatchState[];
  won: number;
  lost: number;
  draw: number;
  scoreAtGivenTime: number;
}

export enum MatchState {
  Won = 'Won',
  Lost = 'Lost',
  Draw = 'Draw'
}
