import { Component, ChangeDetectionStrategy, OnInit, ChangeDetectorRef } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DestroySubject } from '@honoregaming/core';
import { finalize } from 'rxjs/operators';
import { InstantLeagueRound } from '../../models/instant-league-round.model';
import { InstantLeagueService } from '../../services/instant-league.service';

@Component({
  selector: 'hg-instant-league-results',
  templateUrl: './instant-league-results.component.html',
  styleUrls: ['./instant-league-results.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class InstantLeagueResultsComponent extends DestroySubject implements OnInit {
  loading = false;
  error = false;
  rounds: InstantLeagueRound[] = [];
  entryPointId: number;
  skip = 0;
  take = 4;
  hasMore = true;

  constructor(
    private instantLeagueService: InstantLeagueService,
    private cdRef: ChangeDetectorRef,
    private route: ActivatedRoute
  ) {
    super();
    this.route.params.subscribe(params => {
      this.entryPointId = +params.eventCategoryId;
    });
  }

  ngOnInit() {
    this.loadResults();
  }

  loadResults() {
    this.loading = true;
    this.hasMore = false;
    this.instantLeagueService
      .getLeagueResults(this.entryPointId, this.skip, this.take)
      .pipe(
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        result => {
          this.hasMore = result.hasMore;
          this.skip += this.take;
          this.rounds = this.rounds.concat(result.rounds);
        },
        _ => {
          this.error = true;
        }
      );
  }
}
