import { Component, ChangeDetectionStrategy, OnInit, Input, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { DestroySubject, shuffleArray, OddsPreviewerVisibilityService } from '@honoregaming/core';
import { EventBetType, BetCategoryType, Event } from '@honoregaming/types';
import { MessageService, OddsPreviewerState } from '@honoregaming/ui';
import { createBetLineWithSelection, BetSlipService, BetLine } from '@honoregaming/betslip';
import { Location } from '@angular/common';
import { MultipleFlashComponent } from '../../multiple-flash/multiple-flash.component';

@Component({
  selector: 'hg-keno-pick',
  templateUrl: './pick.component.html',
  styleUrls: ['./pick.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class KenoPickComponent extends DestroySubject implements OnInit, OnDestroy {
  @Input()
  event: Event;

  @Input()
  eventBetType: EventBetType;

  betTypeOptions: { [id: number]: string[] } = [];
  computedAmount: number;

  baseNumbers: number[] = [];
  baseSelection: number[] = [];
  flashNumbers: number[] = [];
  flashNumber: number;

  loading = false;
  error = false;
  isEventExpired = false;
  selectionEmpty = true;
  oddsPreviewerState = OddsPreviewerState.Closed;

  constructor(
    private cdRef: ChangeDetectorRef,
    private oddsPreviewerVisibilityService: OddsPreviewerVisibilityService,
    private betSlipService: BetSlipService,
    private messageService: MessageService,
    private location: Location
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(OddsPreviewerState.Closed);
    this.setEvent();
  }

  ngOnDestroy() {
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(OddsPreviewerState.Closed);
  }

  setEvent() {
    this.flashNumbers = [3, 4, 5, 6, 7, 8, 9, 10];
    this.baseNumbers = Array.from(Array(this.eventBetType.designationConfiguration.base.max), (_d, i) => i + 1);
    this.loading = false;
    this.computedAmount = this.eventBetType.baseAmount;
    this.cdRef.markForCheck();
  }

  onBaseSelection(number: number) {
    if (this.baseSelection.indexOf(number) === -1) {
      if (this.baseSelection.length < this.eventBetType.designationConfiguration.base.maxNumberOfItems) {
        this.baseSelection.push(number);
      }
    } else {
      this.baseSelection.splice(this.baseSelection.indexOf(number), 1);
    }
    this.baseSelection.sort((a, b) => a - b);
    this.selectionEmpty = this.isSelectionEmpty();
    this.setBetSlipIconState();
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(this.oddsPreviewerState);
  }

  isSelectionEmpty() {
    return this.baseSelection.length === 0;
  }

  flash(flashNumber) {
    this.baseSelection = [];

    this.baseSelection = shuffleArray([...this.baseNumbers])
      .slice(0, flashNumber)
      .sort((a, b) => a - b);

    this.baseSelection.sort((a, b) => a - b);
    this.selectionEmpty = false;
    this.setBetSlipIconState();
    this.oddsPreviewerVisibilityService.raiseOddsPreviewerVisibilityChanged(this.oddsPreviewerState);
  }

  addToBetslip() {
    const betLine = this.createBetLine();

    this.betSlipService.addBetLine(betLine);
    this.baseSelection = [];
    this.selectionEmpty = this.isSelectionEmpty();
  }

  createBetLine(): BetLine {
    if (!this.eventBetType) {
      return null;
    }
    const maxOdds = this.getMaxOdds();

    return createBetLineWithSelection(
      this.event,
      this.eventBetType,
      this.baseSelection.map(i => i.toString()),
      null,
      BetCategoryType.VirtualFixedOdds,
      null,
      null,
      null,
      null,
      maxOdds
    );
  }

  setBetSlipIconState() {
    this.oddsPreviewerState = OddsPreviewerState.SelectionStakesOpened;
  }

  openPopin() {
    this.messageService
      .sendComponentMessage(MultipleFlashComponent, {
        multipleFlashNumbers: this.flashNumbers
      })
      .closed.subscribe(result => {
        if (result) {
          this.flash(result.flashNumber);
          this.cdRef.markForCheck();
        }
      });
  }

  goBack() {
    this.location.back();
  }

  getMaxOdds() {
    const table = this.eventBetType.maxPayTable;
    if (table) {
      const index = this.baseSelection.length;
      return index ? table[index] : null;
    }

    return null;
  }
}
