import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, OnChanges } from '@angular/core';
import { SelectableEventBetTypeItem } from '@honoregaming/types';
import { RouletteItemSize } from '@honoregaming/ui';

@Component({
  selector: 'hg-spin-and-win-high-low',
  templateUrl: './spin-and-win-high-low.component.html',
  styleUrls: ['./spin-and-win-high-low.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SpinAndWinHighLowComponent implements OnChanges {
  @Input()
  eventBetTypeItems: SelectableEventBetTypeItem[];
  orderedEventBetTypeItems: SelectableEventBetTypeItem[] = [];

  @Output()
  selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  spinAndWinHighLowBetTypes: { [id: string]: number } = {
    Green: 3194,
    Low: 3195,
    High: 3196
  };

  RouletteItemSize = RouletteItemSize;

  constructor() {}

  ngOnChanges() {
    this.orderedEventBetTypeItems = [];
    this.orderedEventBetTypeItems.push(
      this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === this.spinAndWinHighLowBetTypes['Green'])
    );
    this.orderedEventBetTypeItems.push(
      this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === this.spinAndWinHighLowBetTypes['Low'])
    );
    this.orderedEventBetTypeItems.push(
      this.eventBetTypeItems.find(ebti => ebti.betTypeItemId === this.spinAndWinHighLowBetTypes['High'])
    );
  }

  addOrRemoveItemToSelection(eventBetTypeItem: SelectableEventBetTypeItem) {
    this.selectionChanged.emit(eventBetTypeItem);
  }
}
