import { Component, ChangeDetectionStrategy, Input, Output, EventEmitter, OnInit } from '@angular/core';
import { SelectableEventBetTypeItem, EventWithEventBetTypes, Event } from '@honoregaming/types';

@Component({
  selector: 'hg-lucky-loot-event-bet-type-with-event-bet-type-items',
  templateUrl: './lucky-loot-event-bet-type-with-event-bet-type-items.component.html',
  styleUrls: ['./lucky-loot-event-bet-type-with-event-bet-type-items.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LuckyLootEventBetTypeWithEventBetTypeItemsComponent implements OnInit {
  @Input()
  eventBetTypeItems: SelectableEventBetTypeItem[];

  @Input()
  betTypeContext: string;
  total: string;

  @Output()
  selectionChanged = new EventEmitter<SelectableEventBetTypeItem>();

  betTypeIcons: { [name: number]: string } = {
    3370: 'hgv-betTypeItemSumOdd',
    3371: 'hgv-betTypeItemSumEven',
    3372: 'hgv-betTypeItemSumOver',
    3373: 'hgv-betTypeItemSumUnder'
  };

  event: EventWithEventBetTypes<Event>;
  constructor() {}

  ngOnInit() {
    if (this.betTypeContext) {
      this.total = JSON.parse(this.betTypeContext)?.total;
    }
  }

  addOrRemoveItemToSelection(eventBetTypeItem: SelectableEventBetTypeItem) {
    this.selectionChanged.emit(eventBetTypeItem);
  }
}
