import {
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  OnInit,
  HostBinding,
  Inject,
  PLATFORM_ID
} from '@angular/core';
import { EventCategoriesNavigationComponent } from '../event-categories-navigation.component';
import { EventCategoriesService } from '@honoregaming/events';
import { ActivatedRoute, Router } from '@angular/router';
import { scopeToken, Scope } from '@honoregaming/core';
import { isPlatformServer } from '@angular/common';
import { VirtualRaceService } from '../../../services';
import { EventCategory } from '@honoregaming/types';
import { I18nService } from '@honoregaming/i18n';

@Component({
  selector: 'hg-virtual-ui-desktop-event-categories-navigation',
  templateUrl: './event-categories-navigation.component.html',
  styleUrls: ['./event-categories-navigation.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DesktopEventCategoriesNavigationComponent extends EventCategoriesNavigationComponent implements OnInit {
  @HostBinding('class') class = 'desktop-navigation-menu';
  @HostBinding('class.menu-online') get isMenuOnline() {
    return this.scope === Scope.Customer;
  }
  @HostBinding('class.menu-default') get isMenuDefault() {
    return this.scope !== Scope.Customer;
  }

  isServer = isPlatformServer(this.platformId);
  constructor(
    route: ActivatedRoute,
    router: Router,
    eventCategoriesService: EventCategoriesService,
    virtualRaceService: VirtualRaceService,
    @Inject(PLATFORM_ID) private platformId,
    cdRef: ChangeDetectorRef,
    @Inject(scopeToken) public scope: Scope,
    private i18nService: I18nService
  ) {
    super(route, router, eventCategoriesService, virtualRaceService, cdRef, scope);
  }

  getEntryPointName(entrypoint: EventCategory): string {
    return this.i18nService.translateWithFallbackSync(
      'VIRTUAL.FOOTBALL_LEAGUE.' + entrypoint.id + '.NAME',
      entrypoint.name
    );
  }
}
